window.HELP_DATA = {"locale": "zh-Hans", "bundles": [{"schemaVersion": 1, "bundleId": "f90j", "locale": "zh-Hans", "title": "尼康 F90X/F90 操作指南", "tocRoots": ["f90j.t00000c"], "topics": [{"tocLevel": 0, "tocIndex": 0, "searchText": "操作指南（尼康 F90X/F90） 操作指南 （尼康 F90X/F90） 请指定要查阅的项目。 相机 数据后背 主要配件", "tocChildCount": 5, "id": "f90j.t00000c", "tocParent": null, "strings": {"zh-Hans": {"title": "操作指南（尼康 F90X/F90）", "body": "<div class=\"winhelp-topic wh-home-guide\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">操作指南</p><p class=\"wh-p\">（尼康 F90X/F90）</p><p class=\"wh-p\">请指定要查阅的项目。</p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0001af\"><img class=\"wh-inline\" src=\"./assets/f90j/0.webp\" alt=\"\"/>相机</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t015277\"><img class=\"wh-inline\" src=\"./assets/f90j/1.webp\" alt=\"\"/>数据后背</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t028490\"><img class=\"wh-inline\" src=\"./assets/f90j/2.webp\" alt=\"\"/>主要配件</a></p></div></div>", "bodyFormat": "html", "displayTitle": "操作指南（尼康 F90X/F90）"}}}, {"tocLevel": 1, "tocIndex": 0, "searchText": "相机 相机 基本操作篇 曝光模式篇 警告/错误显示篇", "tocChildCount": 3, "id": "f90j.t0001af", "tocParent": "f90j.t00000c", "strings": {"zh-Hans": {"title": "相机", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">相机</p><figure class=\"wh-fig wh-fig-left\"><img src=\"./assets/f90j/3.webp\" alt=\"\"/></figure><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t000279\">相机 - 基本操作篇</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t008b65\">相机 - 曝光模式篇</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00c6e7\">相机 - 警告/错误显示篇</a></p></div></div>", "bodyFormat": "html", "displayTitle": "相机"}}}, {"tocLevel": 2, "tocIndex": 0, "searchText": "相机 - 基本操作篇 相机 - 基本操作篇主开关 两键复位 胶片感光度设置 测光模式设置 曝光模式设置 图像程序设置 胶片过片模式设置 对焦区域设置 对焦模式设置 胶片倒片 曝光补偿设置 闪光同步模式设置 自拍定时器设置 AE 锁定杆 AF-L(对焦锁定)按钮 预览按钮 照明器按钮 接目镜快门", "tocChildCount": 18, "id": "f90j.t000279", "tocParent": "f90j.t0001af", "strings": {"zh-Hans": {"title": "相机 - 基本操作篇", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">相机 - 基本操作篇</p></div><div class=\"wh-block wh-left\"><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t000517\">主开关</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0009c5\">两键复位</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t000fed\">胶片感光度设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t001259\">测光模式设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00158b\">曝光模式设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00400c\">图像程序设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0043d1\">胶片过片模式设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0046ce\">对焦区域设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t004a3b\">对焦模式设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t005114\">胶片倒片</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t005234\">曝光补偿设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t005425\">闪光同步模式设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0080ec\">自拍定时器时间设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t008270\">AE 锁定杆</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t008420\">AF-L（对焦锁定）按钮</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t008618\">预览按钮</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00879f\">照明器按钮</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0089e4\">接目镜快门</a></p></div></div>", "bodyFormat": "html", "displayTitle": "相机 - 基本操作篇"}}}, {"tocLevel": 3, "tocIndex": 0, "searchText": "主开关 <主开关>- 相机的电源 ON/OFF 通过<主开关>和快门按钮进行。将<主开关>移至 ON 位置时电源开启，开启的电源在8秒后自动关闭。半按快门按钮 (按至一半处 ) 之后，相机再次通电，手指离开后8秒关闭。 半按期间，AF镜头进行驱动。 ＊为防止意外开启电源或释放快门，不使用时请将<主开关>关闭。 ＊释放快门时，从快门按钮移开手指后2秒，电源关闭。 ＊通过程序偏移或尼康 Photo Secretary 进行的特殊拍摄设置等，若将<主开关>暂时关闭，则会取消。 ＊使用尼康 Photo Secretary 的自定义设置，可将8秒的半按计时器时间更改为4秒、16秒、30秒或60秒。", "tocChildCount": 0, "id": "f90j.t000517", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "主开关", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;主开关&gt;</p><p class=\"wh-p\">相机的电源 ON/OFF 通过&lt;主开关&gt;和快门按钮进行。将&lt;主开关&gt;移至 ON 位置时电源开启，开启的电源在8秒后自动关闭。</p><p class=\"wh-p\">半按快门按钮（按至一半处） 之后，相机再次通电，手指离开后8秒关闭。 半按期间，AF镜头进行驱动。</p><p class=\"wh-p wh-footnote\">＊为防止意外开启电源或释放快门，不使用时请将&lt;主开关&gt;关闭。</p><p class=\"wh-p wh-footnote\">＊释放快门时，从快门按钮移开手指后2秒，电源关闭。</p><p class=\"wh-p wh-footnote\">＊通过程序偏移或尼康 Photo Secretary 进行的特殊拍摄设置等，若将&lt;主开关&gt;暂时关闭，则会取消。</p><p class=\"wh-p wh-footnote\">＊使用尼康 Photo Secretary 的自定义设置，可将8秒的半按计时器时间更改为4秒、16秒、30秒或60秒。</p></div></div>", "bodyFormat": "html", "displayTitle": "主开关"}}}, {"tocLevel": 3, "tocIndex": 1, "searchText": "两键复位 ＜两键复位＞ 同时按住<复位>按钮和<复位/曝光补偿>按钮（ 带有 标记的两个按钮）约2秒，相机各功能将即时复位到以下状态。 曝光模式 ：P多程序自动（P程序自动） 测光模式 ： 矩阵测光 胶片过片模式： 单张过片 对焦区域 ： 宽对焦区域 闪光同步模式 ： 正常（标准前帘同步） 曝光补偿 ：补偿为零 程序偏移 ：取消 ＊MF-26上设定的以下功能也将同时取消。（设定值会保留） ·包围曝光·多重曝光·N格序列·长时间曝光·间隔定时器·对焦优先 ＊使用尼康 Photo Secretary 或 MF-26，可将曝光、测光、胶片过片、闪光同步各模式及对焦区域复位到所需组合，进行自定义复位设定。 ＊当使用尼康 Photo Secretary 进行自定义设定时，同时按住两个<复位>按钮超过4秒，待显示开始闪烁后松开两按钮，2秒内再次同时按下两个按钮，即可执行取消自定义设定的全部复位。全部复位时，MF-26上设定的各功能（除部分功能外）也与即时复位同样被取消。", "tocChildCount": 0, "id": "f90j.t0009c5", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "两键复位", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">&lt;两键复位&gt;同时按住&lt;复位&gt;按钮 <img class=\"wh-inline\" src=\"./assets/f90j/4.webp\" alt=\"\"/> 和&lt;复位/曝光补偿&gt;按钮 <img class=\"wh-inline\" src=\"./assets/f90j/4.webp\" alt=\"\"/> <img class=\"wh-inline\" src=\"./assets/f90j/5.webp\" alt=\"\"/>（<img class=\"wh-inline\" src=\"./assets/f90j/4.webp\" alt=\"\"/> 带有 标记的两个按钮）约2秒，相机各功能将即时复位到以下状态。</p><p class=\"wh-p wh-spec-row\"><span class=\"wh-spec-label\">曝光模式</span><span class=\"wh-spec-sep\">：</span><span class=\"wh-spec-icon\"><span class=\"wh-bold\">P</span></span><span class=\"wh-spec-value\">多程序自动</span></p><p class=\"wh-p wh-spec-row\"><span class=\"wh-spec-label\">测光模式</span><span class=\"wh-spec-sep\">：</span><span class=\"wh-spec-icon\"><img class=\"wh-inline\" src=\"./assets/f90j/6.webp\" alt=\"\"/></span><span class=\"wh-spec-value\">矩阵测光</span></p><p class=\"wh-p wh-spec-row\"><span class=\"wh-spec-label\">胶片过片模式</span><span class=\"wh-spec-sep\">：</span><span class=\"wh-spec-icon\"><img class=\"wh-inline\" src=\"./assets/f90j/7.webp\" alt=\"\"/></span><span class=\"wh-spec-value\">单张过片</span></p><p class=\"wh-p wh-spec-row\"><span class=\"wh-spec-label\">对焦区域</span><span class=\"wh-spec-sep\">：</span><span class=\"wh-spec-icon\"><img class=\"wh-inline\" src=\"./assets/f90j/8.webp\" alt=\"\"/></span><span class=\"wh-spec-value\">宽对焦区域</span></p><p class=\"wh-p wh-spec-row\"><span class=\"wh-spec-label\">闪光同步模式</span><span class=\"wh-spec-sep\">：</span><span class=\"wh-spec-icon\"><img class=\"wh-inline\" src=\"./assets/f90j/9.webp\" alt=\"\"/></span><span class=\"wh-spec-value\">正常（标准前帘同步）</span></p><p class=\"wh-p wh-spec-row\"><span class=\"wh-spec-label\">曝光补偿</span><span class=\"wh-spec-sep\">：</span><span class=\"wh-spec-icon\"></span><span class=\"wh-spec-value\">补偿为零</span></p><p class=\"wh-p wh-spec-row\"><span class=\"wh-spec-label\">程序偏移</span><span class=\"wh-spec-sep\">：</span><span class=\"wh-spec-icon\"></span><span class=\"wh-spec-value\">取消</span></p><p class=\"wh-p wh-footnote wh-footnote-list\">＊MF-26上设定的以下功能也将同时取消。（设定值会保留） ·包围曝光·多重曝光·N格序列·长时间曝光·间隔定时器·对焦优先</p><p class=\"wh-p wh-footnote\">＊使用尼康 Photo Secretary 或 MF-26，可将曝光、测光、胶片过片、闪光同步各模式及对焦区域复位到所需组合，进行自定义复位设定。</p><p class=\"wh-p wh-footnote\">＊当使用尼康 Photo Secretary 进行自定义设定时，同时按住两个&lt;复位&gt;按钮超过4秒，待显示<img class=\"wh-inline\" src=\"./assets/f90j/10.webp\" alt=\"\"/>开始闪烁后松开两按钮，2秒内再次同时按下两个按钮，即可执行取消自定义设定的全部复位。全部复位时，MF-26上设定的各功能（除部分功能外）也与即时复位同样被取消。</p></div></div>", "bodyFormat": "html", "displayTitle": "两键复位"}}}, {"tocLevel": 3, "tocIndex": 2, "searchText": "胶片感光度设置 ＜胶片感光度设置＞按住<ISO>按钮并转动指令拨盘，可以设置胶片感光度。外部显示面板上点亮 时，使用DX胶片就会自动设置胶片感光度。 如果熄灭该符号并手动设置ISO值，无论是否使用DX胶片，都将按照设定的值进行控制。 ＊ 显示在ISO 6与6400之间。＊通过尼康 Photo Secretary 的自定义设置，也可以指定DX优先，始终根据DX编码自动设置感光度。", "tocChildCount": 0, "id": "f90j.t000fed", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "胶片感光度设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">&lt;胶片感光度设置&gt;按住&lt;ISO&gt;按钮并转动指令拨盘，可以设置胶片感光度。外部显示面板上点亮 <img class=\"wh-inline\" src=\"./assets/f90j/11.webp\" alt=\"\"/> 时，使用DX胶片就会自动设置胶片感光度。</p><p class=\"wh-p\">如果熄灭<img class=\"wh-inline\" src=\"./assets/f90j/11.webp\" alt=\"\"/>并手动设置ISO值，无论是否使用DX胶片，都将按照设定的值进行控制。</p><p class=\"wh-p wh-footnote\">＊<img class=\"wh-inline\" src=\"./assets/f90j/11.webp\" alt=\"\"/> 显示在ISO 6与6400之间。</p><p class=\"wh-p wh-footnote\">＊通过尼康 Photo Secretary 的自定义设置，也可以指定DX优先，始终根据DX编码自动设置感光度。</p></div></div>", "bodyFormat": "html", "displayTitle": "胶片感光度设置"}}}, {"tocLevel": 3, "tocIndex": 3, "searchText": "测光模式设置 ＜测光模式设置＞按住＜测光模式＞按钮并旋转指令拨盘， 矩阵测光、中央重点测光、点测光 可选择其中之一。 * 矩阵测光仅在使用内置CPU的尼克尔镜头时可选择，特别是安装D型镜头（内置距离信息镜头）时，可进行3D八分区矩阵测光。 * 当矩阵测光图标闪烁时，表示因镜头等条件无法进行矩阵测光，已自动切换为中央重点测光。", "tocChildCount": 0, "id": "f90j.t001259", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "测光模式设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;测光模式设置&gt;</p><p class=\"wh-p\">按住&lt;测光模式&gt;按钮并旋转指令拨盘，</p><p class=\"wh-p wh-metering-row\"><img class=\"wh-inline\" src=\"./assets/f90j/6.webp\" alt=\"\"/><span class=\"wh-metering-label\">矩阵测光</span></p><p class=\"wh-p wh-metering-row\"><img class=\"wh-inline\" src=\"./assets/f90j/12.webp\" alt=\"\"/><span class=\"wh-metering-label\">中央重点测光</span></p><p class=\"wh-p wh-metering-row\"><img class=\"wh-inline\" src=\"./assets/f90j/13.webp\" alt=\"\"/><span class=\"wh-metering-label\">点测光</span></p><p class=\"wh-p wh-footnote\">＊<img class=\"wh-inline\" src=\"./assets/f90j/6.webp\" alt=\"\"/>矩阵测光仅在使用内置CPU的尼克尔镜头时可选择，特别是安装D型镜头（内置距离信息镜头）时，可进行3D八分区矩阵测光。</p><p class=\"wh-p wh-footnote\">* 当矩阵测光图标<img class=\"wh-inline\" src=\"./assets/f90j/6.webp\" alt=\"\"/>闪烁时，表示因镜头等条件无法进行矩阵测光，已自动切换为中央重点测光。</p></div></div>", "bodyFormat": "html", "displayTitle": "测光模式设置"}}}, {"tocLevel": 3, "tocIndex": 4, "searchText": "曝光模式设置 ＜曝光模式设置＞按住＜MODE＞按钮并旋转主指令拨盘，即可设置曝光模式。 Ｐ : 多程序自动Ｓ : 快门优先自动Ａ : 光圈优先自动Ｍ : 手动 ＊若使用尼康 Photo Secretary 创建了自定义程序线并传输至相机，曝光模式显示屏会显示“P”，胶片计数器会显示“CP”，形成自定义程序位置，设定至此位置即可使用创建的程序。 ＊P、S 模式仅在使用内置 CPU 的尼克尔镜头时有效。 ＊通过尼康 Photo Secretary 的自定义设置，可将 B 门变更为 T 门。", "tocChildCount": 0, "id": "f90j.t00158b", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "曝光模式设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;曝光模式设置&gt;</p><p class=\"wh-p\">按住&lt;MODE&gt;按钮并旋转主指令拨盘，即可设置曝光模式。</p><p class=\"wh-p wh-program-row\"><span class=\"wh-program-letter\">P</span><span class=\"wh-program-sep\"> : </span><span class=\"wh-program-label\">多程序自动</span></p><p class=\"wh-p wh-program-row\"><span class=\"wh-program-letter\">S</span><span class=\"wh-program-sep\"> : </span><span class=\"wh-program-label\">快门优先自动</span></p><p class=\"wh-p wh-program-row\"><span class=\"wh-program-letter\">A</span><span class=\"wh-program-sep\"> : </span><span class=\"wh-program-label\">光圈优先自动</span></p><p class=\"wh-p wh-program-row\"><span class=\"wh-program-letter\">M</span><span class=\"wh-program-sep\"> : </span><span class=\"wh-program-label\">手动</span></p><p class=\"wh-p wh-footnote\">＊若使用尼康 Photo Secretary 创建了自定义程序线并传输至相机，曝光模式显示屏会显示“P”，胶片计数器会显示“CP”，形成自定义程序位置，设定至此位置即可使用创建的程序。</p><p class=\"wh-p wh-footnote\">＊P、S 模式仅在使用内置 CPU 的尼克尔镜头时有效。</p><p class=\"wh-p wh-footnote\">＊通过尼康 Photo Secretary 的自定义设置，可将 B 门变更为 T 门。</p></div></div>", "bodyFormat": "html", "displayTitle": "曝光模式设置"}}}, {"tocLevel": 3, "tocIndex": 5, "searchText": "图像程序设置 ＜图像程序设置＞按住＜Ps＞按钮并转动指令拨盘，可从任何曝光模式立即切换到图像程序的 Ps 模式。 Po : 人像rE : 红眼减轻（红眼减轻人像）HF : 超焦距（纪念照） LA : 风景 SL : 剪影 SP : 运动 CU : 近摄 ＊图像程序仅在使用内置 CPU 的尼克尔镜头时可用。 ＊使用 rE 模式时，请使用具有预闪功能的闪光灯。 ＊从图像程序切换到普通曝光模式时，按住＜MODE＞按钮并转动指令拨盘即可。 ＊通过尼康 Photo Secretary 的自定义设置，可将 Ps 模式／自定义程序模式下取景器内的模式显示更改为胶片计数器显示。", "tocChildCount": 0, "id": "f90j.t00400c", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "图像程序设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;图像程序设置&gt;</p><p class=\"wh-p\">按住&lt;Ps&gt;按钮并转动指令拨盘，可从任何曝光模式立即切换到图像程序的 Ps 模式。</p><p class=\"wh-p wh-program-row\"><span class=\"wh-program-letter\">Po</span><span class=\"wh-program-sep\"> : </span><span class=\"wh-program-label\">人像</span></p><p class=\"wh-p wh-program-row\"><span class=\"wh-program-letter\">rE</span><span class=\"wh-program-sep\"> : </span><span class=\"wh-program-label\">红眼减轻（红眼减轻人像）</span></p><p class=\"wh-p wh-program-row\"><span class=\"wh-program-letter\">HF</span><span class=\"wh-program-sep\"> : </span><span class=\"wh-program-label\">超焦距（纪念照）</span></p><p class=\"wh-p wh-program-row\"><span class=\"wh-program-letter\">LA</span><span class=\"wh-program-sep\"> : </span><span class=\"wh-program-label\">风景</span></p><p class=\"wh-p wh-program-row\"><span class=\"wh-program-letter\">SL</span><span class=\"wh-program-sep\"> : </span><span class=\"wh-program-label\">剪影</span></p><p class=\"wh-p wh-program-row\"><span class=\"wh-program-letter\">SP</span><span class=\"wh-program-sep\"> : </span><span class=\"wh-program-label\">运动</span></p><p class=\"wh-p wh-program-row\"><span class=\"wh-program-letter\">CU</span><span class=\"wh-program-sep\"> : </span><span class=\"wh-program-label\">近摄</span></p><p class=\"wh-p wh-footnote\">＊图像程序仅在使用内置 CPU 的尼克尔镜头时可用。</p><p class=\"wh-p wh-footnote\">＊使用 rE 模式时，请使用具有预闪功能的闪光灯。</p><p class=\"wh-p wh-footnote\">＊从图像程序切换到普通曝光模式时，按住&lt;MODE&gt;按钮并转动指令拨盘即可。</p><p class=\"wh-p wh-footnote\">＊通过尼康 Photo Secretary 的自定义设置，可将 Ps 模式／自定义程序模式下取景器内的模式显示更改为胶片计数器显示。</p></div></div>", "bodyFormat": "html", "displayTitle": "图像程序设置"}}}, {"tocLevel": 3, "tocIndex": 6, "searchText": "胶片过片模式设置 ＜胶片过片模式设置＞按住 <DRIVE> 按钮并旋转指令拨盘，可选择单张拍摄、高速连拍或低速连拍中的任意一种胶片过片模式。·单张拍摄 每按一次快门按钮拍摄一张照片。 ·高速连拍 F90X：按住快门按钮期间，以约 4.3 张/秒的速度连拍。F90：按住快门按钮期间，以约 3.6 张/秒的速度连拍。 ·低速连拍 按住快门按钮期间，以约 2.0 张/秒的速度连拍。 上述数据基于对焦模式 C 或 M，曝光模式 M，快门速度 1/250 秒以上", "tocChildCount": 0, "id": "f90j.t0043d1", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "胶片过片模式设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;胶片过片模式设置&gt;</p><p class=\"wh-p\">按住 &lt;DRIVE&gt; 按钮并旋转指令拨盘，可选择单张拍摄、高速连拍或低速连拍中的任意一种胶片过片模式。</p><p class=\"wh-p wh-metering-row\"><img class=\"wh-inline\" src=\"./assets/f90j/7.webp\" alt=\"\"/><span class=\"wh-metering-label\">单张拍摄</span></p><p class=\"wh-p\">每按一次快门按钮拍摄一张照片。</p><p class=\"wh-p wh-metering-row\"><img class=\"wh-inline\" src=\"./assets/f90j/14.webp\" alt=\"\"/><span class=\"wh-metering-label\">高速连拍</span></p><p class=\"wh-p\">F90X：按住快门按钮期间，以约 4.3 张/秒的速度连拍。</p><p class=\"wh-p\">F90：按住快门按钮期间，以约 3.6 张/秒的速度连拍。</p><p class=\"wh-p wh-metering-row\"><img class=\"wh-inline\" src=\"./assets/f90j/15.webp\" alt=\"\"/><span class=\"wh-metering-label\">低速连拍</span></p><p class=\"wh-p\">按住快门按钮期间，以约 2.0 张/秒的速度连拍。</p><p class=\"wh-p wh-footnote\">上述数据基于对焦模式 C 或 M、曝光模式 M、快门速度 1/250 秒以上的条件。</p></div></div>", "bodyFormat": "html", "displayTitle": "胶片过片模式设置"}}}, {"tocLevel": 3, "tocIndex": 7, "searchText": "对焦区域设置 ＜对焦区域设置＞按住＜对焦区域切换＞按钮并旋转指令拨盘， 可以在宽对焦区域 与点对焦区域 之间切换。 ·宽对焦区域 由于焦点检测范围较广，易于在对焦区域内捕捉被摄体。除一般拍摄外，尤其适合体育等快速移动的被摄体。 ·点对焦区域 由于焦点检测范围较窄，对焦区域内远近被摄体重叠的概率降低。适合对被摄体的特定部分等目标位置进行精确对焦。", "tocChildCount": 0, "id": "f90j.t0046ce", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "对焦区域设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;对焦区域设置&gt;</p><p class=\"wh-p\">按住 &lt;对焦区域切换&gt; 按钮并旋转指令拨盘，</p><p class=\"wh-p\">可以在宽对焦区域<img class=\"wh-inline\" src=\"./assets/f90j/8.webp\" alt=\"\"/>与点对焦区域<img class=\"wh-inline\" src=\"./assets/f90j/13.webp\" alt=\"\"/>之间切换。</p><p class=\"wh-p wh-metering-row\"><img class=\"wh-inline\" src=\"./assets/f90j/8.webp\" alt=\"\"/><span class=\"wh-metering-label\">宽对焦区域</span></p><p class=\"wh-p\">由于焦点检测范围较广，易于在对焦区域内捕捉被摄体。</p><p class=\"wh-p\">除一般拍摄外，尤其适合体育等快速移动的被摄体。</p><p class=\"wh-p wh-metering-row\"><img class=\"wh-inline\" src=\"./assets/f90j/13.webp\" alt=\"\"/><span class=\"wh-metering-label\">点对焦区域</span></p><p class=\"wh-p\">由于焦点检测范围较窄，对焦区域内远近被摄体重叠的概率降低。</p><p class=\"wh-p\">适合对被摄体的特定部分等目标位置进行精确对焦。</p></div></div>", "bodyFormat": "html", "displayTitle": "对焦区域设置"}}}, {"tocLevel": 3, "tocIndex": 8, "searchText": "对焦模式设置 <对焦模式设置> 使用<对焦模式切换>拨盘，可选择三种对焦模式中的一种。 ·C（连续AF伺服） 在半按快门按钮期间，根据被摄体的移动持续驱动镜头始终保持合焦的模式，无论合焦与否随时都可以释放快门，是释放优先模式。 ·S（单次AF伺服） 一旦合焦后镜头驱动停止，持续半按期间对焦锁定的模式，仅当合焦时才能释放快门，是对焦优先模式。 ·M（手动） 不启动AF，手动旋转距离环进行对焦的模式。此时，当开放F值或合成F值在F5.6以上明亮时，可利用取景器内的对焦显示进行对焦确认的对焦辅助功能。 *使用尼康 Photo Secretary 的自定义设置，可进行以下设置。 ·连续AF伺服时的对焦优先设置 ·单次AF伺服时的释放优先设置 ·单次AF伺服时，用声音通知已合焦 ·将单次AF伺服与连续卷片的胶片过片模式组合使用时，连拍中不进行帧间AF驱动（初始设置为合焦前驱动） *使用尼康 Photo Secretary 或 MF-26 的对焦优先功能，即使在连续AF/手动模式下，也可设置成仅当对焦准确时才能释放快门的对焦优先状态。", "tocChildCount": 0, "id": "f90j.t004a3b", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "对焦模式设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;对焦模式设置&gt;</p><p class=\"wh-p\">使用 &lt;对焦模式切换&gt; 拨盘，可选择三种对焦模式中的一种。</p><p class=\"wh-p wh-metering-row\"><img class=\"wh-inline\" src=\"./assets/f90j/16.webp\" alt=\"\"/><span class=\"wh-metering-label\">C（连续 AF 伺服）</span></p><p class=\"wh-p\">在半按快门按钮期间，根据被摄体的移动持续驱动镜头始终保持合焦的模式，无论合焦与否随时都可以释放快门，是释放优先模式。</p><p class=\"wh-p wh-metering-row\"><img class=\"wh-inline\" src=\"./assets/f90j/17.webp\" alt=\"\"/><span class=\"wh-metering-label\">S（单次 AF 伺服）</span></p><p class=\"wh-p\">一旦合焦后镜头驱动停止，持续半按期间对焦锁定的模式，仅当合焦时才能释放快门，是对焦优先模式。</p><p class=\"wh-p wh-metering-row\"><img class=\"wh-inline\" src=\"./assets/f90j/18.webp\" alt=\"\"/><span class=\"wh-metering-label\">M（手动）</span></p><p class=\"wh-p\">不启动 AF，手动旋转距离环进行对焦的模式。</p><p class=\"wh-p\">此时，当开放 F 值或合成 F 值在 F5.6 以上明亮时，可利用取景器内的对焦显示进行对焦确认的对焦辅助功能。</p><p class=\"wh-p wh-footnote\">＊使用尼康 Photo Secretary 的自定义设置，可进行以下设置。</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">·连续 AF 伺服时的对焦优先设置</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">·单次 AF 伺服时的释放优先设置</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">·单次 AF 伺服时，用声音通知已合焦</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">·将单次 AF 伺服与连续过片的胶片过片模式组合使用时，连拍中不进行帧间 AF 驱动（初始设置为合焦前驱动）</p><p class=\"wh-p wh-footnote\">＊使用尼康 Photo Secretary 或 MF-26 的对焦优先功能，即使在连续 AF/手动模式下，也可设置成仅当对焦准确时才能释放快门的对焦优先状态。</p></div></div>", "bodyFormat": "html", "displayTitle": "对焦模式设置"}}}, {"tocLevel": 3, "tocIndex": 9, "searchText": "胶片倒片 ＜胶片倒片＞同时按下＜倒片＞按钮和＜倒片/ISO＞按钮，倒片开始。倒片过程中胶片计数器递减，完成后显示“E”并马达自动停止。", "tocChildCount": 0, "id": "f90j.t005114", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "胶片倒片", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;胶片倒片&gt;</p><p class=\"wh-p\">同时按下&lt;倒片&gt;按钮和&lt;倒片/ISO&gt;按钮，倒片开始。倒片过程中胶片计数器递减，完成后显示“E”并马达自动停止。</p></div></div>", "bodyFormat": "html", "displayTitle": "胶片倒片"}}}, {"tocLevel": 3, "tocIndex": 10, "searchText": "曝光补偿设置 ＜曝光补偿设置＞ 按下＜曝光补偿＞按钮的同时转动命令拨盘，可在±5档范围内进行曝光补偿。设定曝光补偿后，取景器内外的显示部分将点亮曝光补偿标志 ，提示正在进行曝光补偿。此外，设定后仍可按下＜曝光补偿＞按钮确认补偿量。 ＊ 对于F90X，通过尼康 Photo Secretary的自定义设置，可在A模式下单独使用命令拨盘进行曝光补偿。", "tocChildCount": 0, "id": "f90j.t005234", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "曝光补偿设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;曝光补偿设置&gt;</p><p class=\"wh-p\">按下<img class=\"wh-inline\" src=\"./assets/f90j/4.webp\" alt=\"\"/><img class=\"wh-inline\" src=\"./assets/f90j/5.webp\" alt=\"\"/>&lt;曝光补偿&gt;按钮的同时转动命令拨盘，可在±5档范围内进行曝光补偿。</p><p class=\"wh-p\">设定曝光补偿后，取景器内外的显示部分将点亮曝光补偿标志 <img class=\"wh-inline\" src=\"./assets/f90j/5.webp\" alt=\"\"/> ，提示正在进行曝光补偿。此外，设定后仍可按下&lt;曝光补偿&gt;按钮确认补偿量。</p><p class=\"wh-p wh-footnote\">＊对于F90X，通过尼康 Photo Secretary的自定义设置，可在A模式下单独使用命令拨盘进行曝光补偿。</p></div></div>", "bodyFormat": "html", "displayTitle": "曝光补偿设置"}}}, {"tocLevel": 3, "tocIndex": 11, "searchText": "闪光同步模式设置 <闪光同步模式设置> 按住<同步模式>按钮并旋转指令拨盘，可以选择闪光灯拍摄时的同步模式。･标准 这是通常使用的标准模式，即前帘同步模式。在此模式下，仅当按住同步模式按钮时，才会显示标记。为防止手抖，快门速度不会低于1/60秒。 ＊对于F90X，可以通过使用尼康 Photo Secretary 的自定义设置，在标准前帘同步模式下，将快门速度的低速限值在1秒到1/250秒范围内选择。 ･慢速同步 在P/A模式下设置时，还会根据背景亮度启动最长30秒的低速快门。在HF、LA、SL模式下，会自动设置为慢速同步。 ･后帘同步 这是将闪光灯发光时机定在快门后帘即将开始运行之前的后帘同步模式。后帘同步在低速快门速度下更有效果，因此在P/A模式下也会同时设置为慢速同步。 ＊使用配备NORMAL/REAR同步选择器的SB-26等闪光灯时，切换请在闪光灯侧进行。相机侧的设置无效。 ･红眼减轻闪光 这是进行减轻红眼现象的预闪灯照射的模式。在此模式下拍摄时，请使用具有预闪灯照射功能的闪光灯。", "tocChildCount": 0, "id": "f90j.t005425", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "闪光同步模式设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;闪光同步模式设置&gt;</p><p class=\"wh-p\">按住 &lt;同步模式&gt; 按钮 <img class=\"wh-inline\" src=\"./assets/f90j/9.webp\" alt=\"\"/>并旋转指令拨盘，可以选择闪光灯拍摄时的同步模式。</p><p class=\"wh-p wh-metering-row\"><img class=\"wh-inline\" src=\"./assets/f90j/19.webp\" alt=\"\"/><span class=\"wh-metering-label\">标准</span></p><p class=\"wh-p\">这是通常使用的标准模式，即前帘同步模式。</p><p class=\"wh-p\">在此模式下，仅当按住同步模式按钮时，才会显示<img class=\"wh-inline\" src=\"./assets/f90j/9.webp\" alt=\"\"/>标记。</p><p class=\"wh-p\">为防止手抖，快门速度不会低于 1/60 秒。</p><p class=\"wh-p wh-footnote\">＊对于 F90X，可以通过使用尼康 Photo Secretary 的自定义设置，在标准前帘同步模式下，将快门速度的低速限值在 1 秒到 1/250 秒范围内选择。</p><p class=\"wh-p wh-metering-row\"><img class=\"wh-inline\" src=\"./assets/f90j/20.webp\" alt=\"\"/><span class=\"wh-metering-label\">慢速同步</span></p><p class=\"wh-p\">在 P/A 模式下设置时，还会根据背景亮度启动最长 30 秒的低速快门。</p><p class=\"wh-p\">在 HF、LA、SL 模式下，会自动设置为慢速同步。</p><p class=\"wh-p wh-metering-row\"><img class=\"wh-inline\" src=\"./assets/f90j/21.webp\" alt=\"\"/><span class=\"wh-metering-label\">后帘同步</span></p><p class=\"wh-p\">这是将闪光灯发光时机定在快门后帘即将开始运行之前的后帘同步模式。</p><p class=\"wh-p\">后帘同步在低速快门速度下更有效果，因此在 P/A 模式下也会同时设置为慢速同步。</p><p class=\"wh-p wh-footnote\">＊使用配备 NORMAL/REAR 同步选择器的 SB-26 等闪光灯时，切换请在闪光灯侧进行。相机侧的设置无效。</p><p class=\"wh-p wh-metering-row\"><img class=\"wh-inline\" src=\"./assets/f90j/22.webp\" alt=\"\"/><img class=\"wh-inline\" src=\"./assets/f90j/bm16.webp\" alt=\"\"/><span class=\"wh-metering-label\">红眼减轻闪光</span></p><p class=\"wh-p\">这是进行减轻红眼现象的预闪灯照射的模式。</p><p class=\"wh-p\">在此模式下拍摄时，请使用具有预闪灯照射功能的闪光灯。</p></div></div>", "bodyFormat": "html", "displayTitle": "闪光同步模式设置"}}}, {"tocLevel": 3, "tocIndex": 12, "searchText": "自拍定时器时间设置 <自拍定时器时间设置>按住<自拍定时器>按钮并旋转指令拨盘，可在2秒至30秒范围内以1秒为步长设置自拍定时器的工作时间。按住<自拍定时器>按钮并按下快门按钮，自拍定时器启动，在设定时间结束后自动拍摄。", "tocChildCount": 0, "id": "f90j.t0080ec", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "自拍定时器时间设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;自拍定时器时间设置&gt;</p><p class=\"wh-p\">按住<img class=\"wh-inline\" src=\"./assets/f90j/24.webp\" alt=\"\"/>&lt;自拍定时器&gt;按钮并旋转指令拨盘，可在2秒至30秒范围内以1秒为步长设置自拍定时器的工作时间。</p><p class=\"wh-p\">按住<img class=\"wh-inline\" src=\"./assets/f90j/24.webp\" alt=\"\"/>&lt;自拍定时器&gt;按钮并按下快门按钮，自拍定时器启动，在设定时间结束后自动拍摄。</p></div></div>", "bodyFormat": "html", "displayTitle": "自拍定时器时间设置"}}}, {"tocLevel": 3, "tocIndex": 13, "searchText": "AE 锁定杆 ＜AE 锁定杆＞当曝光模式设为 AE 模式（手动曝光以外的模式）时，向侧面滑动 <AE 锁定> 杆，滑动期间即可执行 AE 锁定，固定曝光值。 ＊使用尼康 Photo Secretary 或 MF-26 指定 AE 与 AF 的同时锁定时，操作 <AE 锁定> 杆或 <AF-L> 按钮中的任意一个，即可同时锁定曝光和对焦。", "tocChildCount": 0, "id": "f90j.t008270", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "AE 锁定杆", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;AE 锁定杆&gt;</p><p class=\"wh-p\">当曝光模式设为 AE 模式（手动曝光以外的模式）时，向侧面滑动 &lt;AE 锁定&gt; 杆，滑动期间即可执行 AE 锁定，固定曝光值。</p><p class=\"wh-p wh-footnote\">＊使用尼康 Photo Secretary 或 MF-26 指定 AE 与 AF 的同时锁定时，操作 &lt;AE 锁定&gt; 杆或 &lt;AF-L&gt; 按钮中的任意一个，即可同时锁定曝光和对焦。</p></div></div>", "bodyFormat": "html", "displayTitle": "AE 锁定杆"}}}, {"tocLevel": 3, "tocIndex": 14, "searchText": "AF-L（对焦锁定）按钮 <AF-L（对焦锁定）按钮> 在自动对焦拍摄中想要锁定对焦时，按下<AF-L>按钮，即可在按住期间锁定对焦。尤其在使用快门按钮无法锁定对焦的连续AF伺服时有效。 ＊使用尼康 Photo Secretary 或 MF-26 指定 AE 与 AF 同时锁定后，通过操作 <AE锁定> 杆或 <AF-L> 按钮中的任意一个，即可同时锁定曝光和对焦。", "tocChildCount": 0, "id": "f90j.t008420", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "AF-L（对焦锁定）按钮", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;AF-L（对焦锁定）按钮&gt;</p><p class=\"wh-p\">在自动对焦拍摄中想要锁定对焦时，按下&lt;AF-L&gt;按钮，即可在按住期间锁定对焦。尤其在使用快门按钮无法锁定对焦的连续AF伺服时有效。</p><p class=\"wh-p wh-footnote\">＊使用尼康 Photo Secretary 或 MF-26 指定 AE 与 AF 同时锁定后，通过操作 &lt;AE锁定&gt; 杆或 &lt;AF-L&gt; 按钮中的任意一个，即可同时锁定曝光和对焦。</p></div></div>", "bodyFormat": "html", "displayTitle": "AF-L（对焦锁定）按钮"}}}, {"tocLevel": 3, "tocIndex": 15, "searchText": "预览按钮 按下<预览按钮>时，在按住期间，光圈会收缩到光圈环上设定的光圈值，可以确认景深等。 * 按住<预览>按钮期间不会进行测光，并且也无法释放快门。", "tocChildCount": 0, "id": "f90j.t008618", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "预览按钮", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;预览按钮&gt;</p><p class=\"wh-p\">按下&lt;预览按钮&gt;时，在按住期间，光圈会收缩到光圈环上设定的光圈值，可以确认景深等。</p><p class=\"wh-p wh-footnote\">＊按住&lt;预览&gt;按钮期间不会进行测光，并且也无法释放快门。</p></div></div>", "bodyFormat": "html", "displayTitle": "预览按钮"}}}, {"tocLevel": 3, "tocIndex": 16, "searchText": "照明器按钮 ＜照明器按钮＞按下<照明器>按钮，外部显示屏的照明器点亮，取景器内显示的照明器也会变亮。点亮的照明器在半按定时器关闭后熄灭。另外，照明器点亮时再次按下<照明器>按钮，仅外部显示屏的照明器熄灭。 ＊取景器内显示的照明器会根据被摄体的亮度自动变亮。＊半按快门期间，外部显示屏的照明器熄灭。", "tocChildCount": 0, "id": "f90j.t00879f", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "照明器按钮", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;照明器按钮&gt;</p><p class=\"wh-p\">按下&lt;照明器&gt;按钮，外部显示屏的照明器点亮，取景器内显示的照明器也会变亮。点亮的照明器在半按定时器关闭后熄灭。另外，照明器点亮时再次按下&lt;照明器&gt;按钮，仅外部显示屏的照明器熄灭。</p><p class=\"wh-p wh-footnote\">＊取景器内显示的照明器会根据被摄体的亮度自动变亮。</p><p class=\"wh-p wh-footnote\">＊半按快门期间，外部显示屏的照明器熄灭。</p></div></div>", "bodyFormat": "html", "displayTitle": "照明器按钮"}}}, {"tocLevel": 3, "tocIndex": 17, "searchText": "接目镜快门 ＜接目镜快门＞拨动取景器接目部分旁边的<接目镜快门>拨杆，即可关闭接目镜快门。接目镜快门用于防止从取景器接目部分进入的逆光引起测光误差，在AE模式（手动曝光以外的模式）下进行自拍或遥控拍摄等操作时，请在释放快门前将其关闭。", "tocChildCount": 0, "id": "f90j.t0089e4", "tocParent": "f90j.t000279", "strings": {"zh-Hans": {"title": "接目镜快门", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;接目镜快门&gt;</p><p class=\"wh-p\">拨动取景器接目部分旁边的&lt;接目镜快门&gt;拨杆，即可关闭接目镜快门。接目镜快门用于防止从取景器接目部分进入的逆光引起测光误差，在AE模式（手动曝光以外的模式）下进行自拍或遥控拍摄等操作时，请在释放快门前将其关闭。</p></div></div>", "bodyFormat": "html", "displayTitle": "接目镜快门"}}}, {"tocLevel": 2, "tocIndex": 1, "searchText": "相机 - 曝光模式篇 相机 - 曝光模式篇 P·多程序自动 程序偏移 S·快门优先自动 A·光圈优先自动 M·手动 Po·人像 rE·红眼减轻 HF·超焦距 LA·风景 SL·剪影 SP·运动 CU·特写 CP·自定义程序", "tocChildCount": 13, "id": "f90j.t008b65", "tocParent": "f90j.t0001af", "strings": {"zh-Hans": {"title": "相机 - 曝光模式篇", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">相机 - 曝光模式篇</p></div><div class=\"wh-block wh-left\"><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t008d0f\">P·多程序自动</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t008e1b\">程序偏移</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00901e\">S·快门优先自动</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00914e\">A・光圈优先自动</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00928b\">M・手动</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0093c1\">Po·人像</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0094a6\">rE・防红眼</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t009673\">HF・超焦距</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00c00c\">LA · 风景</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00c0e6\">SL・剪影</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00c275\">SP・运动</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00c3b8\">CU・特写</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00c4bf\">CP・自定义程序</a></p></div></div>", "bodyFormat": "html", "displayTitle": "相机 - 曝光模式篇"}}}, {"tocLevel": 3, "tocIndex": 0, "searchText": "P·多程序自动 ＜P·多程序自动曝光＞根据镜头的焦距和亮度，相机自动控制最佳光圈与快门速度组合的曝光模式。可以进行程序偏移。", "tocChildCount": 0, "id": "f90j.t008d0f", "tocParent": "f90j.t008b65", "strings": {"zh-Hans": {"title": "P·多程序自动", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;P·多程序自动&gt;</p><p class=\"wh-p\">根据镜头的焦距和亮度，相机自动控制最佳光圈与快门速度组合的曝光模式。可以进行程序偏移。</p></div></div>", "bodyFormat": "html", "displayTitle": "P·多程序自动"}}}, {"tocLevel": 3, "tocIndex": 1, "searchText": "程序偏移 ＜程序偏移＞图像程序可在保持正确曝光的同时，根据创作意图改变快门速度与光圈的组合。F90X的情况下，旋转指令拨盘以1/3级步进变化，偏移期间曝光模式显示“P”的右上角点亮“＊”。F90的情况下，旋转指令拨盘以1级步进变化，偏移期间曝光模式显示“P”闪烁。程序偏移的解除，除半按定时器关闭时会自动解除外，也可通过将指令拨盘移回偏移位置、关闭＜主开关＞、即时复位、或将曝光模式临时变更至其他模式来完成。", "tocChildCount": 0, "id": "f90j.t008e1b", "tocParent": "f90j.t008b65", "strings": {"zh-Hans": {"title": "程序偏移", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;程序偏移&gt;</p><p class=\"wh-p\">图像程序可在保持正确曝光的同时，根据创作意图改变快门速度与光圈的组合。</p><p class=\"wh-p\">F90X的情况下，旋转指令拨盘以1/3级步进变化，偏移期间曝光模式显示“P”的右上角点亮“＊”。</p><p class=\"wh-p\">F90的情况下，旋转指令拨盘以1级步进变化，偏移期间曝光模式显示“P”闪烁。</p><p class=\"wh-p\">程序偏移的解除，除半按定时器关闭时会自动解除外，也可通过将指令拨盘移回偏移位置、关闭&lt;主开关&gt;、即时复位、或将曝光模式临时变更至其他模式来完成。</p></div></div>", "bodyFormat": "html", "displayTitle": "程序偏移"}}}, {"tocLevel": 3, "tocIndex": 2, "searchText": "S·快门优先自动 ＜S·快门优先自动＞ 选择快门速度后，光圈会自动控制的曝光模式。可用超高速1/8000秒凝固瞬间，或使用低速快门强调动感，自由表现被摄体的动态。", "tocChildCount": 0, "id": "f90j.t00901e", "tocParent": "f90j.t008b65", "strings": {"zh-Hans": {"title": "S·快门优先自动", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">选择快门速度后，光圈会自动控制的曝光模式。可用超高速1/8000秒凝固瞬间，或使用低速快门强调动感，自由表现被摄体的动态。</p></div></div>", "bodyFormat": "html", "displayTitle": "S·快门优先自动"}}}, {"tocLevel": 3, "tocIndex": 3, "searchText": "A・光圈优先自动 ＜A·光圈优先自动＞选择光圈后，快门速度自动控制的曝光模式。可开大光圈虚化背景突出主体，或收缩光圈表现纵深感，活用景深（合焦范围）。", "tocChildCount": 0, "id": "f90j.t00914e", "tocParent": "f90j.t008b65", "strings": {"zh-Hans": {"title": "A・光圈优先自动", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">选择光圈后，快门速度自动控制的曝光模式。可开大光圈虚化背景突出主体，或收缩光圈表现纵深感，活用景深（合焦范围）。</p></div></div>", "bodyFormat": "html", "displayTitle": "A・光圈优先自动"}}}, {"tocLevel": 3, "tocIndex": 4, "searchText": "M・手动 ＜M·手动＞这是一种可以自由设定快门速度和光圈值的曝光模式。通过观察曝光指示器的显示，可以轻松进行有意的欠曝或过曝控制，适合进行创意表现时使用。", "tocChildCount": 0, "id": "f90j.t00928b", "tocParent": "f90j.t008b65", "strings": {"zh-Hans": {"title": "M・手动", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">这是一种可以自由设定快门速度和光圈值的曝光模式。通过观察曝光指示器的显示，可以轻松进行有意的欠曝或过曝控制，适合进行创意表现时使用。</p></div></div>", "bodyFormat": "html", "displayTitle": "M・手动"}}}, {"tocLevel": 3, "tocIndex": 5, "searchText": "Po·人像 ＜Po·人像＞虚化背景、突出被摄人物的模式。使用85mm至200mm左右的明亮望远镜头效果佳。", "tocChildCount": 0, "id": "f90j.t0093c1", "tocParent": "f90j.t008b65", "strings": {"zh-Hans": {"title": "Po·人像", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">虚化背景、突出被摄人物的模式。使用85mm至200mm左右的明亮望远镜头效果佳。</p></div></div>", "bodyFormat": "html", "displayTitle": "Po·人像"}}}, {"tocLevel": 3, "tocIndex": 6, "searchText": "rE・防红眼 <rE·红眼减轻>这是为减轻红眼现象而进行灯光预闪的人像模式。使用闪光灯拍摄人物时，瞳孔有时会被拍成红色。这种现象称为红眼现象，在暗处瞳孔放大时容易发生。该模式在人像模式的基础上，在闪光灯正式发光前进行灯光预闪，使红眼现象不易发生。", "tocChildCount": 0, "id": "f90j.t0094a6", "tocParent": "f90j.t008b65", "strings": {"zh-Hans": {"title": "rE・防红眼", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;rE・防红眼&gt;</p><p class=\"wh-p\">这是为减轻红眼现象而进行灯光预闪的人像模式。使用闪光灯拍摄人物时，瞳孔有时会被拍成红色。这种现象称为红眼现象，在暗处瞳孔放大时容易发生。该模式在人像模式的基础上，在闪光灯正式发光前进行灯光预闪，使红眼现象不易发生。</p></div></div>", "bodyFormat": "html", "displayTitle": "rE・防红眼"}}}, {"tocLevel": 3, "tocIndex": 7, "searchText": "HF・超焦距 ＜HF 超焦距＞是一种同时清晰拍摄人物和背景的模式。最适合旅途回忆和纪念照片的拍摄。使用广角到标准程度的镜头效果较好。", "tocChildCount": 0, "id": "f90j.t009673", "tocParent": "f90j.t008b65", "strings": {"zh-Hans": {"title": "HF・超焦距", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">是一种同时清晰拍摄人物和背景的模式。最适合旅途回忆和纪念照片的拍摄。使用广角到标准程度的镜头效果较好。</p></div></div>", "bodyFormat": "html", "displayTitle": "HF・超焦距"}}}, {"tocLevel": 3, "tocIndex": 8, "searchText": "LA · 风景 ＜LA·风景＞从近景到远景，如实再现海洋、山脉等美丽自然和印象深刻的景色氛围的模式。可根据被摄体使用从广角到望远的镜头。", "tocChildCount": 0, "id": "f90j.t00c00c", "tocParent": "f90j.t008b65", "strings": {"zh-Hans": {"title": "LA · 风景", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">从近景到远景，如实再现海洋、山脉等美丽自然和印象深刻的景色氛围的模式。可根据被摄体使用从广角到望远的镜头。</p></div></div>", "bodyFormat": "html", "displayTitle": "LA · 风景"}}}, {"tocLevel": 3, "tocIndex": 9, "searchText": "SL・剪影 ＜SL·剪影＞此模式可在以美丽的自然风景等为背景、且亮度差较大时，营造出剪影般的氛围。 例如，以晚霞天空为背景拍摄人物时，曝光会对准晚霞天空，人物则呈现为剪影效果。 要发挥此模式的效果，请不使用闪光灯，仅用自然光拍摄。 镜头从广角到望远，可根据被摄体使用。", "tocChildCount": 0, "id": "f90j.t00c0e6", "tocParent": "f90j.t008b65", "strings": {"zh-Hans": {"title": "SL・剪影", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;SL・剪影&gt;</p><p class=\"wh-p\">此模式可在以美丽的自然风景等为背景、且亮度差较大时，营造出剪影般的氛围。例如，以晚霞天空为背景拍摄人物时，曝光会对准晚霞天空，人物则呈现为剪影效果。要发挥此模式的效果，请不使用闪光灯，仅用自然光拍摄。镜头从广角到望远，可根据被摄体使用。</p></div></div>", "bodyFormat": "html", "displayTitle": "SL・剪影"}}}, {"tocLevel": 3, "tocIndex": 10, "searchText": "SP・运动 ＜SP･运动＞在凝固激烈运动被摄体瞬间动作的同时，通过保留些许模糊来表现动感的模式。利用速度感和背景虚化效果，突出被摄体。使用80mm至300mm左右的远摄镜头效果较佳。", "tocChildCount": 0, "id": "f90j.t00c275", "tocParent": "f90j.t008b65", "strings": {"zh-Hans": {"title": "SP・运动", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">在凝固激烈运动被摄体瞬间动作的同时，通过保留些许模糊来表现动感的模式。利用速度感和背景虚化效果，突出被摄体。使用80mm至300mm左右的远摄镜头效果较佳。</p></div></div>", "bodyFormat": "html", "displayTitle": "SP・运动"}}}, {"tocLevel": 3, "tocIndex": 11, "searchText": "CU・特写 ＜CU·近摄＞用于近距离拍摄昆虫和花草的模式。使用较浅的景深，使主体突出，背景美丽虚化。使用微距镜头效果更佳。", "tocChildCount": 0, "id": "f90j.t00c3b8", "tocParent": "f90j.t008b65", "strings": {"zh-Hans": {"title": "CU・特写", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\"><CU·近摄>用于近距离拍摄昆虫和花草的模式。使用较浅的景深，使主体突出，背景美丽虚化。使用微距镜头效果更佳。</p></div></div>", "bodyFormat": "html", "displayTitle": "CU・特写"}}}, {"tocLevel": 3, "tocIndex": 12, "searchText": "CP・自定义程序 ＜CP·自定义程序＞这是在尼康 Photo Secretary 中创建自定义程序线并传输至相机时可使用的模式。在自定义程序线上，可设置三个拐点，因此您可以根据喜好自由创建并使用程序，例如快门优先式程序、光圈优先式程序，或根据亮度将两者结合的程序等。通过调用曝光模式显示部的「P」和胶片计数器显示部的「CP」，即可使用自定义程序。", "tocChildCount": 0, "id": "f90j.t00c4bf", "tocParent": "f90j.t008b65", "strings": {"zh-Hans": {"title": "CP・自定义程序", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">这是在尼康 Photo Secretary 中创建自定义程序线并传输至相机时可使用的模式。在自定义程序线上，可设置三个拐点，因此您可以根据喜好自由创建并使用程序，例如快门优先式程序、光圈优先式程序，或根据亮度将两者结合的程序等。通过调用曝光模式显示部的「P」和胶片计数器显示部的「CP」，即可使用自定义程序。</p></div></div>", "bodyFormat": "html", "displayTitle": "CP・自定义程序"}}}, {"tocLevel": 2, "tocIndex": 2, "searchText": "相机 - 警告/错误显示篇 相机 - 警告/错误显示篇 FEE 闪烁 F-- 点亮 End 闪烁 HI 点亮 Lo 点亮 buLb 闪烁 P 模式显示闪烁 S 模式显示闪烁 P* 显示点亮 (F90X) P 显示闪烁 (F90) 矩阵测光显示闪烁 曝光补偿标记点亮 曝光补偿标记闪烁 电池显示闪烁 胶片装入标记闪烁 卷片显示闪烁 倒片显示闪烁 曝光指示器闪烁 红眼减轻标记闪烁 Err、ISO、DX 标记闪烁 就绪灯闪烁 Ps 模式显示闪烁 SL 显示闪烁 Err 显示闪烁 显示闪烁 显示点亮 (F90X) 电子系统手册标记闪烁 胶片计数器 0 闪烁 FuL 闪烁", "tocChildCount": 30, "id": "f90j.t00c6e7", "tocParent": "f90j.t0001af", "strings": {"zh-Hans": {"title": "相机 - 警告/错误显示篇", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">相机 - 警告/错误显示篇</p></div><div class=\"wh-block wh-left\"><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00cc71\">FEE闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00ceae\">F-- 亮起</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00d10a\">End闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00d1c0\">HI 指示灯亮起</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00d2f6\">Lo点亮</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00d4b7\">BULB闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t00d6d1\">Ｐ 模式显示闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t010032\">S模式显示闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0100c7\">P*指示灯亮起（F90X）</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t01019b\">P 显示闪烁 (F90)</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t01026a\"><img class=\"wh-inline\" src=\"./assets/f90j/6.webp\" alt=\"\"/>矩阵测光显示闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0103b8\"><img class=\"wh-inline\" src=\"./assets/f90j/5.webp\" alt=\"\"/>曝光补偿指示灯点亮</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t01060c\"><img class=\"wh-inline\" src=\"./assets/f90j/5.webp\" alt=\"\"/>曝光补偿标记的闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0107b3\"><img class=\"wh-inline\" src=\"./assets/f90j/25.webp\" alt=\"\"/>电池指示灯闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0109c4\"><img class=\"wh-inline\" src=\"./assets/f90j/26.webp\" alt=\"\"/>胶片装入标记闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t010d1c\"><img class=\"wh-inline\" src=\"./assets/f90j/27.webp\" alt=\"\"/>卷片显示闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t010fae\"><img class=\"wh-inline\" src=\"./assets/f90j/28.webp\" alt=\"\"/>倒片显示闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t01128b\"><img class=\"wh-inline\" src=\"./assets/f90j/29.webp\" alt=\"\"/>曝光指示灯闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t011493\"><img class=\"wh-inline\" src=\"./assets/f90j/30.webp\" alt=\"\"/><img class=\"wh-inline\" src=\"./assets/f90j/31.webp\" alt=\"\"/>红眼减轻标记闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t011664\"><img class=\"wh-inline\" src=\"./assets/f90j/32.webp\" alt=\"\"/><img class=\"wh-inline\" src=\"./assets/f90j/33.webp\" alt=\"\"/>显示闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t014105\">Err、ISO、DX 闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0141f2\">就绪灯闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t01449c\">Ps 模式显示闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t014663\">SL 显示闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t014760\">ERR闪烁显示</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t014abc\"><img class=\"wh-inline\" src=\"./assets/f90j/10.webp\" alt=\"\"/>显示闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t014d38\"><img class=\"wh-inline\" src=\"./assets/f90j/34.webp\" alt=\"\"/>显示点亮</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t014e86\"><img class=\"wh-inline\" src=\"./assets/f90j/35.webp\" alt=\"\"/>电子系统手帐标记闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t015039\">胶片计数器0闪烁</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t01515b\">FuL闪烁</a></p></div></div>", "bodyFormat": "html", "displayTitle": "相机 - 警告/错误显示篇"}}}, {"tocLevel": 3, "tocIndex": 0, "searchText": "FEE闪烁 ＜FEE闪烁＞ 有以下两种情况，任一情况下快门都会自动锁定。① P、Ps、S 模式指示灯点亮时 镜头光圈未设为最小光圈（数值最大的光圈值）。请将光圈设为最小光圈。 ② P、Ps 模式指示灯同时闪烁时 闪光灯未设为 TTL 模式。请将闪光灯切换至 TTL 模式，或将相机曝光模式设为 A 或 M 模式。", "tocChildCount": 0, "id": "f90j.t00cc71", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "FEE闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;FEE闪烁&gt;</p><p class=\"wh-p\">有以下两种情况，任一情况下快门都会自动锁定。</p><p class=\"wh-p\">① P、Ps、S 模式指示灯点亮时</p><p class=\"wh-p\">镜头光圈未设为最小光圈（数值最大的光圈值）。请将光圈设为最小光圈。</p><p class=\"wh-p\">② P、Ps 模式指示灯同时闪烁时</p><p class=\"wh-p\">闪光灯未设为 TTL 模式。请将闪光灯切换至 TTL 模式，或将相机曝光模式设为 A 或 M 模式。</p></div></div>", "bodyFormat": "html", "displayTitle": "FEE闪烁"}}}, {"tocLevel": 3, "tocIndex": 1, "searchText": "F-- 亮起 ＜F-- 亮起＞ ① 当安装了非CPU内藏尼克尔镜头，或未安装镜头时，这是正常的显示。 如果安装的是CPU内藏尼克尔镜头，则会显示光圈数值。 ② 按住＜预览按钮＞期间，光圈显示为F--，快门将自动锁定。 松开＜预览按钮＞，光圈显示即会恢复。", "tocChildCount": 0, "id": "f90j.t00ceae", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "F-- 亮起", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;F-- 亮起&gt;</p><p class=\"wh-p\">① 当安装了非 CPU 内置尼克尔镜头，或未安装镜头时，这是正常的显示。</p><p class=\"wh-p\">如果安装的是 CPU 内置尼克尔镜头，则会显示光圈数值。</p><p class=\"wh-p\">② 按住&lt;预览按钮&gt;期间，光圈显示为 F--，快门将自动锁定。</p><p class=\"wh-p\">松开&lt;预览按钮&gt;，光圈显示即会恢复。</p></div></div>", "bodyFormat": "html", "displayTitle": "F-- 亮起"}}}, {"tocLevel": 3, "tocIndex": 2, "searchText": "End闪烁 ＜End闪烁＞胶片已拍完，请进行倒片操作将其倒回。", "tocChildCount": 0, "id": "f90j.t00d10a", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "End闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;End闪烁&gt;</p><p class=\"wh-p\">胶片已拍完，请进行倒片操作将其倒回。</p></div></div>", "bodyFormat": "html", "displayTitle": "End闪烁"}}}, {"tocLevel": 3, "tocIndex": 3, "searchText": "HI 指示灯亮起 ＜HI 指示灯亮起＞被摄体过亮，已超出相机控制范围。S模式时请将快门速度设为高速侧；A模式时请缩小光圈。若警告仍不消失，或处于P、Ps模式时，请使用ND滤镜拍摄。", "tocChildCount": 0, "id": "f90j.t00d1c0", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "HI 指示灯亮起", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;HI 指示灯亮起&gt;</p><p class=\"wh-p\">被摄体过亮，已超出相机控制范围。</p><p class=\"wh-p\">S 模式时请将快门速度设为高速侧。</p><p class=\"wh-p\">A 模式时请缩小光圈。</p><p class=\"wh-p\">若警告仍不消失，或处于 P、Ps 模式时，请使用 ND 滤镜拍摄。</p></div></div>", "bodyFormat": "html", "displayTitle": "HI 指示灯亮起"}}}, {"tocLevel": 3, "tocIndex": 4, "searchText": "Lo点亮 ＜Lo点亮＞被摄体过暗，超出相机控制范围。S模式下，请将快门速度设为较低值。A模式下，请开大光圈。如果警告仍未消除，或在P、Ps模式下，请使用闪光灯。另外，即使使用闪光灯，若设定了慢速同步或后帘同步，仍会显示Lo。（此时Lo表示背景偏暗，但仍可拍摄。）", "tocChildCount": 0, "id": "f90j.t00d2f6", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "Lo点亮", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;Lo点亮&gt;</p><p class=\"wh-p\">被摄体过暗，超出相机控制范围。</p><p class=\"wh-p\">S 模式下，请将快门速度设为较低值。</p><p class=\"wh-p\">A 模式下，请开大光圈。</p><p class=\"wh-p\">如果警告仍未消除，或在 P、Ps 模式下，请使用闪光灯。</p><p class=\"wh-p\">另外，即使使用闪光灯，若设定了慢速同步或后帘同步，仍会显示 Lo。（此时 Lo 表示背景偏暗，但仍可拍摄。）</p></div></div>", "bodyFormat": "html", "displayTitle": "Lo点亮"}}}, {"tocLevel": 3, "tocIndex": 5, "searchText": "BULB闪烁 ＜BULB闪烁＞表示在B门模式下无法控制。有以下两种情况，快门会自动锁定。 ①若设定为S模式 在S模式下无法设为B门。请设置为B门以外的快门速度，或重新设为M模式。 ②若设定了AE包围曝光 在B门模式下无法进行AE包围曝光。请设置为B门以外的快门速度，或解除AE包围曝光。", "tocChildCount": 0, "id": "f90j.t00d4b7", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "BULB闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;BULB闪烁&gt;</p><p class=\"wh-p\">表示在 B 门模式下无法控制。有以下两种情况，快门会自动锁定。</p><p class=\"wh-p\">① 若设定为 S 模式</p><p class=\"wh-p\">在 S 模式下无法设为 B 门。请设置为 B 门以外的快门速度，或重新设为 M 模式。</p><p class=\"wh-p\">② 若设定了 AE 包围曝光</p><p class=\"wh-p\">在 B 门模式下无法进行 AE 包围曝光。请设置为 B 门以外的快门速度，或解除 AE 包围曝光。</p></div></div>", "bodyFormat": "html", "displayTitle": "BULB闪烁"}}}, {"tocLevel": 3, "tocIndex": 6, "searchText": "Ｐ 模式显示闪烁 ＜P 模式显示闪烁＞ ①除CPU内置尼克尔镜头外，无法进行 P 模式的控制。 如果就这样拍摄，将自动以 A 模式进行控制。 ②如果除了 P 模式显示外，FEE 也在闪烁，则表示闪光灯未设置为 TTL 模式。 快门将自动锁定。请将闪光灯改为 TTL 模式，或将相机的曝光模式重新设置为 A 或 M 模式。", "tocChildCount": 0, "id": "f90j.t00d6d1", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "Ｐ 模式显示闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;Ｐ 模式显示闪烁&gt;</p><p class=\"wh-p\">① 除 CPU 内置尼克尔镜头外，无法进行 P 模式的控制。</p><p class=\"wh-p\">如果就这样拍摄，将自动以 A 模式进行控制。</p><p class=\"wh-p\">② 如果除了 P 模式显示外，FEE 也在闪烁，则表示闪光灯未设置为 TTL 模式。</p><p class=\"wh-p\">快门将自动锁定。请将闪光灯改为 TTL 模式，或将相机的曝光模式重新设置为 A 或 M 模式。</p></div></div>", "bodyFormat": "html", "displayTitle": "Ｐ 模式显示闪烁"}}}, {"tocLevel": 3, "tocIndex": 7, "searchText": "S模式显示闪烁 ＜Ｓ模式显示闪烁＞ 除CPU内置尼克尔镜头外，无法控制S模式。如果直接拍摄，将自动以A模式控制。", "tocChildCount": 0, "id": "f90j.t010032", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "S模式显示闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">除CPU内置尼克尔镜头外，无法控制S模式。如果直接拍摄，将自动以A模式控制。</p></div></div>", "bodyFormat": "html", "displayTitle": "S模式显示闪烁"}}}, {"tocLevel": 3, "tocIndex": 8, "searchText": "P*指示灯亮起（F90X） ＜P*显示点亮＞ (F90X)执行程序偏移时，P模式显示右上角的*会亮起。将偏移量设为0，*熄灭。", "tocChildCount": 0, "id": "f90j.t0100c7", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "P*指示灯亮起（F90X）", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\"><P*显示点亮> (F90X)执行程序偏移时，P模式显示右上角的*会亮起。将偏移量设为0，*熄灭。</p></div></div>", "bodyFormat": "html", "displayTitle": "P*指示灯亮起（F90X）"}}}, {"tocLevel": 3, "tocIndex": 9, "searchText": "P 显示闪烁 (F90) ＜P 显示闪烁＞ (F90) 执行程序偏移时，P 模式显示会闪烁。将偏移量设为 0，闪烁将被消除。", "tocChildCount": 0, "id": "f90j.t01019b", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "P 显示闪烁 (F90)", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">(F90) 执行程序偏移时，P 模式显示会闪烁。将偏移量设为 0，闪烁将被消除。</p></div></div>", "bodyFormat": "html", "displayTitle": "P 显示闪烁 (F90)"}}}, {"tocLevel": 3, "tocIndex": 10, "searchText": "矩阵测光显示闪烁 ＜矩阵测光指示闪烁＞ 当使用非CPU内置尼克尔镜头时，由于无法进行矩阵测光，此时表示相机已自动切换至中央重点测光模式。", "tocChildCount": 0, "id": "f90j.t01026a", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "矩阵测光显示闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;矩阵测光显示闪烁&gt;</p><figure class=\"wh-fig wh-fig-center\"><img src=\"./assets/f90j/6.webp\" alt=\"\"/></figure><p class=\"wh-p\">当使用非 CPU 内置尼克尔镜头时，由于无法进行矩阵测光，此时表示相机已自动切换至中央重点测光模式。</p></div></div>", "bodyFormat": "html", "displayTitle": "<img class=\"wh-inline\" src=\"./assets/f90j/6.webp\" alt=\"\"/>矩阵测光显示闪烁"}}}, {"tocLevel": 3, "tocIndex": 11, "searchText": "曝光补偿指示灯点亮 ＜曝光补偿指示灯亮起＞ ①当设定了曝光补偿时点亮。 ②当用配件设定了闪光补偿时，只有取景器内的曝光补偿指示点亮。 ③在F90X的情况下，通过使用尼康 Photo Secretary的自定义设置，在A模式下设定了简易曝光补偿时点亮。", "tocChildCount": 0, "id": "f90j.t0103b8", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "曝光补偿指示灯点亮", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;曝光补偿指示灯点亮&gt;</p><figure class=\"wh-fig wh-fig-center\"><img src=\"./assets/f90j/5.webp\" alt=\"\"/></figure><p class=\"wh-p\">① 当设定了曝光补偿时点亮。</p><p class=\"wh-p\">② 当用配件设定了闪光补偿时，只有取景器内的曝光补偿指示点亮。</p><p class=\"wh-p\">③ 在 F90X 的情况下，通过使用尼康 Photo Secretary 的自定义设置，在 A 模式下设定了简易曝光补偿时点亮。</p></div></div>", "bodyFormat": "html", "displayTitle": "<img class=\"wh-inline\" src=\"./assets/f90j/5.webp\" alt=\"\"/>曝光补偿指示灯点亮"}}}, {"tocLevel": 3, "tocIndex": 12, "searchText": "曝光补偿标记的闪烁 ＜曝光补偿标记的闪烁＞ 表示已设置自动曝光包围或闪光灯包围。此外，在M模式下设置自动曝光包围时，快门速度显示也会闪烁，表示包围曝光导致快门速度发生变化。", "tocChildCount": 0, "id": "f90j.t01060c", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "曝光补偿标记的闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;曝光补偿标记的闪烁&gt;</p><figure class=\"wh-fig wh-fig-center\"><img src=\"./assets/f90j/5.webp\" alt=\"\"/></figure><p class=\"wh-p\">表示已设置自动曝光包围或闪光灯包围。</p><p class=\"wh-p\">此外，在 M 模式下设置自动曝光包围时，快门速度显示也会闪烁，表示包围曝光导致快门速度发生变化。</p></div></div>", "bodyFormat": "html", "displayTitle": "<img class=\"wh-inline\" src=\"./assets/f90j/5.webp\" alt=\"\"/>曝光补偿标记的闪烁"}}}, {"tocLevel": 3, "tocIndex": 13, "searchText": "电池指示灯闪烁 ＜电池指示灯闪烁＞ 电池指示灯闪烁时，表示电池电量不足，请更换新电池。如果同时Err指示也在闪烁，可能发生了误动作，请将＜主开关＞关闭，然后更换电池。另外，当电池指示灯点亮时，表示电池即将耗尽，请准备备用电池。", "tocChildCount": 0, "id": "f90j.t0107b3", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "电池指示灯闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;电池指示灯闪烁&gt;</p><figure class=\"wh-fig wh-fig-center\"><img src=\"./assets/f90j/25.webp\" alt=\"\"/></figure><p class=\"wh-p\">电池指示灯闪烁时，表示电池电量不足，请更换新电池。</p><p class=\"wh-p\">如果同时 Err 指示也在闪烁，可能发生了误动作，请将&lt;主开关&gt;关闭，然后更换电池。</p><p class=\"wh-p\">另外，当电池指示灯为<img class=\"wh-inline\" src=\"./assets/f90j/25.webp\" alt=\"\"/>的状态而点亮时，表示电池即将耗尽，请准备备用电池。</p></div></div>", "bodyFormat": "html", "displayTitle": "<img class=\"wh-inline\" src=\"./assets/f90j/25.webp\" alt=\"\"/>电池指示灯闪烁"}}}, {"tocLevel": 3, "tocIndex": 14, "searchText": "胶片装入标记闪烁 ＜胶片装载标记闪烁＞ 当胶片装载标记闪烁并且胶片过片显示熄灭时，存在以下两种状态。（如果胶片过片显示也闪烁，请参阅“卷片显示闪烁”或“倒片显示闪烁”的相关条目。） ①胶片空送时 胶片未充分抽出。请重新装入胶片，然后再次按下快门按钮。 ②胶片倒片刚结束时 胶片倒片已结束。请确认胶片计数器“E”显示，然后取出胶片。", "tocChildCount": 0, "id": "f90j.t0109c4", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "胶片装入标记闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;胶片装入标记闪烁&gt;</p><figure class=\"wh-fig wh-fig-center\"><img src=\"./assets/f90j/26.webp\" alt=\"\"/></figure><p class=\"wh-p\">当胶片装入标记闪烁且胶片过片显示熄灭时，有以下两种状态。（若胶片过片显示也在闪烁，请参阅「卷片显示闪烁」或「倒片显示闪烁」条目。）</p><p class=\"wh-p\">① 胶片空送时</p><p class=\"wh-p\">胶片未充分拉出。请重新装入胶片，然后再次按下快门按钮。</p><p class=\"wh-p\">② 胶片倒片刚结束时</p><p class=\"wh-p\">胶片倒片已结束。请确认胶片计数器上的「E」显示，然后取出胶片。</p></div></div>", "bodyFormat": "html", "displayTitle": "<img class=\"wh-inline\" src=\"./assets/f90j/26.webp\" alt=\"\"/>胶片装入标记闪烁"}}}, {"tocLevel": 3, "tocIndex": 15, "searchText": "卷片显示闪烁 ＜过片显示闪烁＞ 胶片仓内标志和胶片过片显示以过片方向闪烁时，有以下两种情况。①End显示也闪烁时 胶片已用完。请进行倒片操作。 ②胶片计数器显示“E”时 是胶片空送错误。请重新装入胶片，然后再次按下快门按钮。", "tocChildCount": 0, "id": "f90j.t010d1c", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "卷片显示闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;卷片显示闪烁&gt;</p><figure class=\"wh-fig wh-fig-center\"><img src=\"./assets/f90j/27.webp\" alt=\"\"/></figure><p class=\"wh-p\">当胶片装入标记与胶片过片显示以卷片方向闪烁时，有以下两种状态。</p><p class=\"wh-p\">① End 显示也闪烁时</p><p class=\"wh-p\">胶片已拍完，请进行倒片操作。</p><p class=\"wh-p\">② 胶片计数器显示「E」时</p><p class=\"wh-p\">属于胶片空送错误。请重新装入胶片，然后再次按下快门按钮。</p></div></div>", "bodyFormat": "html", "displayTitle": "<img class=\"wh-inline\" src=\"./assets/f90j/27.webp\" alt=\"\"/>卷片显示闪烁"}}}, {"tocLevel": 3, "tocIndex": 16, "searchText": "倒片显示闪烁 ＜倒片显示闪烁＞ 当胶片存在标记和胶片过片显示以倒片方向闪烁时，有以下两种状态。①电池指示闪烁时 倒片过程中电池耗尽，因而中途停止。请更换电池后，再次进行倒片操作。 ②电池指示未闪烁时 表示在倒片过程中由于打开了后盖而中途停止。请立即关闭后盖，再次进行倒片操作。", "tocChildCount": 0, "id": "f90j.t010fae", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "倒片显示闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;倒片显示闪烁&gt;</p><figure class=\"wh-fig wh-fig-center\"><img src=\"./assets/f90j/28.webp\" alt=\"\"/></figure><p class=\"wh-p\">当胶片装入标记与胶片过片显示以倒片方向闪烁时，有以下两种状态。</p><p class=\"wh-p\">① 电池指示<img class=\"wh-inline\" src=\"./assets/f90j/25.webp\" alt=\"\"/>闪烁时</p><p class=\"wh-p\">倒片过程中电池耗尽，因而中途停止。请更换电池后，再次进行倒片操作。</p><p class=\"wh-p\">② 电池指示未闪烁时</p><p class=\"wh-p\">表示在倒片过程中由于打开了后盖而中途停止。请立即关闭后盖，再次进行倒片操作。</p></div></div>", "bodyFormat": "html", "displayTitle": "<img class=\"wh-inline\" src=\"./assets/f90j/28.webp\" alt=\"\"/>倒片显示闪烁"}}}, {"tocLevel": 3, "tocIndex": 17, "searchText": "曝光指示灯闪烁 ＜曝光指示器闪烁＞ 在M模式下，被摄体过亮或过暗，超出了相机的测光范围。如果被摄体过暗导致曝光不足（曝光指示器显示“－”），请使用闪光灯。如果被摄体过亮导致曝光过度（曝光指示器显示“＋”），请使用ND滤镜。", "tocChildCount": 0, "id": "f90j.t01128b", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "曝光指示灯闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;曝光指示灯闪烁&gt;</p><figure class=\"wh-fig wh-fig-center\"><img src=\"./assets/f90j/29.webp\" alt=\"\"/></figure><p class=\"wh-p\">在 M 模式下，被摄体过亮或过暗，超出了相机的测光范围。如果被摄体过暗导致曝光不足（曝光指示器显示「－」），请使用闪光灯。如果被摄体过亮导致曝光过度（曝光指示器显示「＋」），请使用 ND 滤镜。</p></div></div>", "bodyFormat": "html", "displayTitle": "<img class=\"wh-inline\" src=\"./assets/f90j/29.webp\" alt=\"\"/>曝光指示灯闪烁"}}}, {"tocLevel": 3, "tocIndex": 18, "searchText": "红眼减轻标记闪烁 ＜红眼减轻标记闪烁＞ 当闪光同步模式的红眼减轻发光模式或图像程序的rE（红眼减轻）模式被设定，且闪光灯没有灯光预闪功能时，红眼减轻标记会闪烁。此时若释放快门，将以标准的前帘同步模式进行拍摄。", "tocChildCount": 0, "id": "f90j.t011493", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "红眼减轻标记闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;红眼减轻标记闪烁&gt;</p><p class=\"wh-p\"><img class=\"wh-inline\" src=\"./assets/f90j/30.webp\" alt=\"\"/><img class=\"wh-inline\" src=\"./assets/f90j/31.webp\" alt=\"\"/></p><p class=\"wh-p\">当闪光同步模式的红眼减轻发光模式或图像程序的 rE（红眼减轻）模式被设定，且闪光灯没有灯光预闪功能时，红眼减轻标记会闪烁。此时若释放快门，将以标准的前帘同步模式进行拍摄。</p></div></div>", "bodyFormat": "html", "displayTitle": "<img class=\"wh-inline\" src=\"./assets/f90j/30.webp\" alt=\"\"/><img class=\"wh-inline\" src=\"./assets/f90j/31.webp\" alt=\"\"/>红眼减轻标记闪烁"}}}, {"tocLevel": 3, "tocIndex": 19, "searchText": "显示闪烁 ＜显示闪烁＞取景器内的对焦指示部分 闪烁时，自动对焦无法完成合焦。 ①被摄体非常暗时，可使用闪光灯SB-26等主动式辅助光进行自动对焦拍摄。 ②被摄体的对比度（明暗差）不分明时，请先用与被摄体在同一距离处的对比度明显的物体进行暂时对焦，锁定对焦后再恢复构图拍摄。 ③其他场合，请将对焦模式设为M，手动转动镜头上的距离环，在取景屏的磨砂面上进行对焦拍摄。", "tocChildCount": 0, "id": "f90j.t011664", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "显示闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">＜<img class=\"wh-inline\" src=\"./assets/f90j/32.webp\" alt=\"\"/><img class=\"wh-inline\" src=\"./assets/f90j/33.webp\" alt=\"\"/>显示闪烁＞</p><p class=\"wh-p\">取景器内的对焦指示部分 <img class=\"wh-inline\" src=\"./assets/f90j/32.webp\" alt=\"\"/><img class=\"wh-inline\" src=\"./assets/f90j/33.webp\" alt=\"\"/> 闪烁时，自动对焦无法完成合焦。</p><p class=\"wh-p\">① 被摄体非常暗时，可使用闪光灯 SB-26 等主动式辅助光进行自动对焦拍摄。</p><p class=\"wh-p\">② 被摄体的对比度（明暗差）不分明时，请先用与被摄体在同一距离处的对比度明显的物体进行暂时对焦，锁定对焦后再恢复构图拍摄。</p><p class=\"wh-p\">③ 其他场合，请将对焦模式设为 M，手动转动镜头上的距离环，在取景屏的磨砂面上进行对焦拍摄。</p></div></div>", "bodyFormat": "html", "displayTitle": "<img class=\"wh-inline\" src=\"./assets/f90j/32.webp\" alt=\"\"/><img class=\"wh-inline\" src=\"./assets/f90j/33.webp\" alt=\"\"/>显示闪烁"}}}, {"tocLevel": 3, "tocIndex": 20, "searchText": "Err、ISO、DX 闪烁 ＜Err、ISO、DX 闪烁＞虽然设置为DX模式，但所装入的胶片不是DX胶片。此时，Err显示也会闪烁，快门会自动锁定。请手动设置胶片感光度。", "tocChildCount": 0, "id": "f90j.t014105", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "Err、ISO、DX 闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">虽然设置为DX模式，但所装入的胶片不是DX胶片。此时，Err显示也会闪烁，快门会自动锁定。请手动设置胶片感光度。</p></div></div>", "bodyFormat": "html", "displayTitle": "Err、ISO、DX 闪烁"}}}, {"tocLevel": 3, "tocIndex": 21, "searchText": "就绪灯闪烁 ＜准备指示灯闪烁＞①当以红色闪烁时 闪光灯自动调光拍摄结果可能曝光不足。请确认调光范围，必要时重新拍摄。 ②当以绿色闪烁时 虽然设置了闪光灯包围曝光，但闪光灯电源未打开。 ③当红色和橙色交替闪烁时 虽然设置了闪光灯包围曝光，但闪光灯未设为TTL模式。", "tocChildCount": 0, "id": "f90j.t0141f2", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "就绪灯闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;就绪灯闪烁&gt;</p><p class=\"wh-p\">① 当以红色闪烁时</p><p class=\"wh-p\">闪光灯自动调光拍摄结果可能曝光不足。请确认调光范围，必要时重新拍摄。</p><p class=\"wh-p\">② 当以绿色闪烁时</p><p class=\"wh-p\">虽然设置了闪光灯包围曝光，但闪光灯电源未打开。</p><p class=\"wh-p\">③ 当红色和橙色交替闪烁时</p><p class=\"wh-p\">虽然设置了闪光灯包围曝光，但闪光灯未设为 TTL 模式。</p></div></div>", "bodyFormat": "html", "displayTitle": "就绪灯闪烁"}}}, {"tocLevel": 3, "tocIndex": 22, "searchText": "Ps 模式显示闪烁 ＜Ps模式显示闪烁＞ ①使用非CPU内置尼克尔镜头时，无法控制Ps模式。 此时，快门会自动锁定。请重新设置为A或M模式。 ②除了Ps模式显示外，如果FEE也闪烁，则闪光灯未设为TTL模式。 快门会自动锁定。请将闪光灯切换为TTL模式，或将相机曝光模式重新设为A或M模式。", "tocChildCount": 0, "id": "f90j.t01449c", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "Ps 模式显示闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;Ps 模式显示闪烁&gt;</p><p class=\"wh-p\">① 使用非 CPU 内置尼克尔镜头时，无法控制 Ps 模式。</p><p class=\"wh-p\">此时，快门会自动锁定。请重新设置为 A 或 M 模式。</p><p class=\"wh-p\">② 除了 Ps 模式显示外，如果 FEE 也闪烁，则闪光灯未设为 TTL 模式。</p><p class=\"wh-p\">快门会自动锁定。请将闪光灯切换为 TTL 模式，或将相机曝光模式重新设为 A 或 M 模式。</p></div></div>", "bodyFormat": "html", "displayTitle": "Ps 模式显示闪烁"}}}, {"tocLevel": 3, "tocIndex": 23, "searchText": "SL 显示闪烁 ＜SL指示灯闪烁＞已设置为剪影模式，但闪光灯电源已开启。可以继续拍摄，但近景无法获得剪影效果。", "tocChildCount": 0, "id": "f90j.t014663", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "SL 显示闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\"><SL指示灯闪烁>已设置为剪影模式，但闪光灯电源已开启。可以继续拍摄，但近景无法获得剪影效果。</p><p class=\"wh-p\"><span class=\"wh-fsize-20\"></span></p></div></div>", "bodyFormat": "html", "displayTitle": "SL 显示闪烁"}}}, {"tocLevel": 3, "tocIndex": 24, "searchText": "ERR闪烁显示 <Err 显示闪烁> ①ISO、DX 标记同时闪烁时 尽管设置为 DX 模式，但装入的胶片不是 DX 胶片。此时，快门将被自动锁定。请手动设定胶片感光度。 ②电池标记同时闪烁时 电池电量已耗尽。可能引起误操作，请将<主开关>设为 OFF，并更换电池。 ③上述以外的情况 发生了某种异常。如果按下快门后显示消失，则相机已自动修复，没有问题。但是，如果显示仍不消失或频繁发生，请将相机送至购买相机的商店或最近的尼康服务站。", "tocChildCount": 0, "id": "f90j.t014760", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "ERR闪烁显示", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;ERR闪烁显示&gt;</p><p class=\"wh-p\">① ISO、DX 标记同时闪烁时</p><p class=\"wh-p\">尽管设置为 DX 模式，但装入的胶片不是 DX 胶片。此时，快门将被自动锁定。请手动设定胶片感光度。</p><p class=\"wh-p\">② 电池标记同时闪烁时</p><p class=\"wh-p\">电池电量已耗尽。可能引起误操作，请将&lt;主开关&gt;设为 OFF，并更换电池。</p><p class=\"wh-p\">③ 上述以外的情况</p><p class=\"wh-p\">发生了某种异常。如果按下快门后显示消失，则相机已自动修复，没有问题。但是，如果显示仍不消失或频繁发生，请将相机送至购买相机的商店或最近的尼康服务站。</p></div></div>", "bodyFormat": "html", "displayTitle": "ERR闪烁显示"}}}, {"tocLevel": 3, "tocIndex": 25, "searchText": "显示闪烁 ＜显示闪烁＞使用尼康 Photo Secretary 设置了自定义功能时 会点亮，但如果两键复位操作持续4秒以上， 标记将开始闪烁。该闪烁表示确认全部复位，以解除自定义设置的内容（MF-26 上设定的部分功能除外）。此时，一旦手指离开按钮并在2秒内进行两键复位操作，即可进行全部复位。如果停止两键复位操作并经过2秒以上，则会从闪烁恢复为点亮，全部复位不会执行。", "tocChildCount": 0, "id": "f90j.t014abc", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "显示闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">＜<img class=\"wh-inline\" src=\"./assets/f90j/10.webp\" alt=\"\"/>显示闪烁＞</p><p class=\"wh-p\">使用尼康 Photo Secretary 设置了自定义功能时，<img class=\"wh-inline\" src=\"./assets/f90j/10.webp\" alt=\"\"/> 会点亮；但如果两键复位操作持续 4 秒以上，<img class=\"wh-inline\" src=\"./assets/f90j/10.webp\" alt=\"\"/> 标记将开始闪烁。该闪烁表示确认全部复位，以解除自定义设置的内容（MF-26 上设定的部分功能除外）。</p><p class=\"wh-p\">此时，一旦手指离开按钮并在 2 秒内进行两键复位操作，即可进行全部复位。</p><p class=\"wh-p\">如果停止两键复位操作并经过 2 秒以上，则会从闪烁恢复为点亮，全部复位不会执行。</p></div></div>", "bodyFormat": "html", "displayTitle": "<img class=\"wh-inline\" src=\"./assets/f90j/10.webp\" alt=\"\"/>显示闪烁"}}}, {"tocLevel": 3, "tocIndex": 26, "searchText": "显示点亮 ＜点亮＞ (F90X) 自定义设置中“测光偏差显示”设为“开启”时，矩阵测光时会显示与中央重点测光的测光偏差。偏差显示期间 会点亮。", "tocChildCount": 0, "id": "f90j.t014d38", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "显示点亮", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">＜<img class=\"wh-inline\" src=\"./assets/f90j/34.webp\" alt=\"\"/>显示点亮＞</p><p class=\"wh-p\">自定义设置中将「测光偏差显示」设为「开启」时，矩阵测光时会显示与中央重点测光的测光偏差。偏差显示期间 <img class=\"wh-inline\" src=\"./assets/f90j/34.webp\" alt=\"\"/> 会点亮。</p></div></div>", "bodyFormat": "html", "displayTitle": "<img class=\"wh-inline\" src=\"./assets/f90j/34.webp\" alt=\"\"/>显示点亮"}}}, {"tocLevel": 3, "tocIndex": 27, "searchText": "电子系统手帐标记闪烁 ＜电子系统手帐标记闪烁＞ 当使用尼康 Photo Secretary 进行特殊拍摄设定时，电子系统手帐标记会闪烁。一旦将＜主开关＞关闭一次，特殊拍摄设定即被解除，电子系统手帐标记也会熄灭。", "tocChildCount": 0, "id": "f90j.t014e86", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "电子系统手帐标记闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;电子系统手帐标记闪烁&gt;</p><figure class=\"wh-fig wh-fig-center\"><img src=\"./assets/f90j/35.webp\" alt=\"\"/></figure><p class=\"wh-p\">当使用尼康 Photo Secretary 进行特殊拍摄设定时，电子系统手帐标记会闪烁。一旦将&lt;主开关&gt;关闭一次，特殊拍摄设定即被解除，电子系统手帐标记也会熄灭。</p></div></div>", "bodyFormat": "html", "displayTitle": "<img class=\"wh-inline\" src=\"./assets/f90j/35.webp\" alt=\"\"/>电子系统手帐标记闪烁"}}}, {"tocLevel": 3, "tocIndex": 28, "searchText": "胶片计数器0闪烁 ＜胶卷计数器闪烁显示0＞当外部显示面板的胶卷计数器闪烁显示0时，表示正在写入第0张数据。请确认MF-26的写入数据后按下快门按钮。", "tocChildCount": 0, "id": "f90j.t015039", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "胶片计数器0闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">当外部显示面板的胶卷计数器闪烁显示0时，表示正在写入第0张数据。请确认MF-26的写入数据后按下快门按钮。</p><p class=\"wh-p\"><span class=\"wh-fsize-20\"></span></p></div></div>", "bodyFormat": "html", "displayTitle": "胶片计数器0闪烁"}}}, {"tocLevel": 3, "tocIndex": 29, "searchText": "FuL闪烁 ＜ＦｕＬ闪烁＞ 存储拍摄数据的内存已满。此时快门会自动锁定。请使用尼康 Photo Secretary 读取拍摄数据。", "tocChildCount": 0, "id": "f90j.t01515b", "tocParent": "f90j.t00c6e7", "strings": {"zh-Hans": {"title": "FuL闪烁", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;FuL闪烁&gt;</p><p class=\"wh-p\">存储拍摄数据的内存已满。此时快门会自动锁定。请使用尼康 Photo Secretary 读取拍摄数据。</p></div></div>", "bodyFormat": "html", "displayTitle": "FuL闪烁"}}}, {"tocLevel": 1, "tocIndex": 1, "searchText": "数据后背操作篇 数据后背操作篇 多功能控制后背 MF-26 世界时数据后背 MF-25", "tocChildCount": 2, "id": "f90j.t015277", "tocParent": "f90j.t00000c", "strings": {"zh-Hans": {"title": "数据后背操作篇", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">数据后背操作篇</p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t01534a\">多功能控制机背 MF-26</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t024f71\">世界时间数据后背 MF-25</a></p></div></div>", "bodyFormat": "html", "displayTitle": "数据后背操作篇"}}}, {"tocLevel": 2, "tocIndex": 0, "searchText": "多功能控制机背 MF-26 マルチコントロールバック ＭＦ－２６ 基本操作 基本设置 数据印记 特殊拍摄设置 闪光补偿设置 自定义功能设置", "tocChildCount": 6, "id": "f90j.t01534a", "tocParent": "f90j.t015277", "strings": {"zh-Hans": {"title": "多功能控制机背 MF-26", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">多功能控制机背 MF-26</p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t01544a\"><img class=\"wh-inline\" src=\"./assets/f90j/bm1.webp\" alt=\"\"/>MF-26-基本操作</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t01962d\">MF-26-基本设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t01c88d\">MF-26 数据印刻</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t01d809\">MF-26-特殊摄影设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t02447c\">闪光曝光补偿设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t02479a\">MF-26 自定义功能设置</a></p></div></div>", "bodyFormat": "html", "displayTitle": "多功能控制机背 MF-26"}}}, {"tocLevel": 3, "tocIndex": 0, "searchText": "MF-26-基本操作 多功能控制后背 MF-26－基本操作功能的设置方法 功能取消方法 <FUNCTION>按钮 <MODE>按钮 <SELECT>按钮 <ADJUST>按钮 <START/STOP>按钮 <SET/RESET>按钮 <PRINT>按钮", "tocChildCount": 9, "id": "f90j.t01544a", "tocParent": "f90j.t01534a", "strings": {"zh-Hans": {"title": "MF-26-基本操作", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">MF-26-基本操作</p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t015578\">功能设置方法</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0183aa\">功能解除方法</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t01858e\">&lt;FUNCTION&gt;按钮</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t018b03\">&lt;MODE&gt;按钮</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t018ef9\">\"SELECT\"按钮</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t018fff\">\"ADJUST\"按钮</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0190c4\">&lt;START/STOP&gt;按钮</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0191e1\">“SET/RESET”按钮</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t019491\"><img class=\"wh-inline\" src=\"./assets/f90j/40.webp\" alt=\"\"/>&lt;PRINT&gt;按钮</a></p></div></div>", "bodyFormat": "html", "displayTitle": "MF-26-基本操作"}}}, {"tocLevel": 4, "tocIndex": 0, "searchText": "功能设置方法 ＜功能设置方法＞一般功能设置方法为打开相机的＜主开关＞，按如下步骤操作。另外，MF-26的设置除了以下说明的方法外，还可使用尼康 Photo Secretary 进行。 ①按住<FUNCTION>按钮的同时旋转指令拨盘，使要选择的功能显示旁的机能选择显示点亮。 ②若所选功能包含多个选项，则按住<MODE>按钮的同时旋转指令拨盘，选择其中之一。 ③按住<SELECT>按钮的同时旋转指令拨盘，选择要修改的数值。所选数值将闪烁。 ④按住<ADJUST>按钮的同时旋转指令拨盘，修改所选数值。 ⑤按住<SELECT>按钮的同时旋转指令拨盘，使闪烁的数值恢复常亮状态。 ⑥按下<SET/RESET>按钮，使功能显示旁的设定显示或点亮。 ⑦按下<FUNCTION>按钮，从部分显示画面切换至完整显示画面。 ⑧若需要数据打印，则按下<PRINT>按钮，使点亮。 打印数据的种类可通过<MODE>按钮与指令拨盘进行选择。", "tocChildCount": 0, "id": "f90j.t015578", "tocParent": "f90j.t01544a", "strings": {"zh-Hans": {"title": "功能设置方法", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;功能设置方法&gt;</p><p class=\"wh-p\">一般功能设置方法为打开相机的&lt;主开关&gt;，按如下步骤操作。</p><p class=\"wh-p\">另外，MF-26 的设置除了以下说明的方法外，还可使用尼康 Photo Secretary 进行。</p><p class=\"wh-p\">① 按住&lt;FUNCTION&gt;按钮的同时旋转指令拨盘，使要选择的功能显示旁的机能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>点亮。</p><p class=\"wh-p\">② 若所选功能包含多个选项，则按住&lt;MODE&gt;按钮的同时旋转指令拨盘，选择其中之一。</p><p class=\"wh-p\">③ 按住&lt;SELECT&gt;按钮的同时旋转指令拨盘，选择要修改的数值。所选数值将闪烁。</p><p class=\"wh-p\">④ 按住&lt;ADJUST&gt;按钮的同时旋转指令拨盘，修改所选数值。</p><p class=\"wh-p\">⑤ 按住&lt;SELECT&gt;按钮的同时旋转指令拨盘，使闪烁的数值恢复常亮状态。</p><p class=\"wh-p\">⑥ 按下&lt;SET/RESET&gt;按钮，使功能显示旁的设定显示<img class=\"wh-inline\" src=\"./assets/f90j/38.webp\" alt=\"\"/>或<img class=\"wh-inline\" src=\"./assets/f90j/39.webp\" alt=\"\"/>点亮。</p><p class=\"wh-p\">⑦ 按下&lt;FUNCTION&gt;按钮，从部分显示画面切换至完整显示画面。</p><p class=\"wh-p\">⑧ 若需要数据印入，则按下&lt;PRINT&gt;按钮，使<img class=\"wh-inline\" src=\"./assets/f90j/40.webp\" alt=\"\"/>指示灯点亮。</p><p class=\"wh-p\"><a class=\"wh-link\" href=\"#topic/f90j.t01c937\">印入数据的种类</a>可通过&lt;MODE&gt;按钮与指令拨盘进行选择。</p></div></div>", "bodyFormat": "html", "displayTitle": "功能设置方法"}}}, {"tocLevel": 4, "tocIndex": 1, "searchText": "功能解除方法 ＜功能解除方法＞ 一般功能的解除方法是将相机的＜主开关＞打开，按以下步骤操作。 ① 按下<FUNCTION>按钮并转动指令拨盘，使要解除功能的指示旁的功能选择指示点亮，然后按下<SET/RESET>按钮，熄灭设定显示或该显示。 ② 按下<FUNCTION>按钮，从部分显示画面切换到全显示画面。", "tocChildCount": 0, "id": "f90j.t0183aa", "tocParent": "f90j.t01544a", "strings": {"zh-Hans": {"title": "功能解除方法", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;功能解除方法&gt;</p><p class=\"wh-p\">一般功能的解除方法是将相机的&lt;主开关&gt;打开，按以下步骤操作。</p><p class=\"wh-p\">① 按下&lt;FUNCTION&gt;按钮并转动指令拨盘，使要解除功能的指示旁的功能选择指示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>点亮，然后按下&lt;SET/RESET&gt;按钮，熄灭设定显示<img class=\"wh-inline\" src=\"./assets/f90j/38.webp\" alt=\"\"/>或<img class=\"wh-inline\" src=\"./assets/f90j/39.webp\" alt=\"\"/>。</p><p class=\"wh-p\">② 按下&lt;FUNCTION&gt;按钮，从部分显示画面切换到全显示画面。</p></div></div>", "bodyFormat": "html", "displayTitle": "功能解除方法"}}}, {"tocLevel": 4, "tocIndex": 2, "searchText": "FUNCTION 按钮 ＜FUNCTION＞按钮 1) 与指令拨盘组合，选择以下功能的按钮。 选择后，所选功能显示旁边功能选择指示灯点亮。 DATA（数据模式） N.SEQ（N张顺序） BKT （AE和闪光灯包围曝光） M EXP（多重曝光） LONG （长时间曝光） INT （间隔定时器） FCS PRIOR （对焦优先） AE/AF-L （AE和AF同时锁定） PRINT LEVEL（数据打印亮度级别） CUSTOM （自定义复位设置） 闪光灯曝光补偿 2) 按下<FUNCTION>按钮，可将功能设置后的部分显示画面切换为全显示画面。另外，从部分显示画面到全显示画面的变更，如果30秒内不操作MF-26的按钮，将自动进行。 ・部分显示画面 在设置各功能时，为便于操作，将与该功能无关的显示消除的画面。 ・全显示画面 除了设置各功能时的显示画面外，显示所有已设置的各种功能的设定显示等必要信息的画面。", "tocChildCount": 0, "id": "f90j.t01858e", "tocParent": "f90j.t01544a", "strings": {"zh-Hans": {"title": "FUNCTION 按钮", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;FUNCTION&gt;按钮</p><p class=\"wh-p\">1) 与指令拨盘配合，用于选择以下功能的按钮。选择后，所选功能显示旁的功能选择指示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>点亮。</p><p class=\"wh-p\">DATA（数据模式）</p><p class=\"wh-p\">　N.SEQ（N张顺序）</p><p class=\"wh-p\">　BKT（AE和闪光灯包围曝光）</p><p class=\"wh-p\">　M EXP（多重曝光）</p><p class=\"wh-p\">　LONG（长时间曝光）</p><p class=\"wh-p\">&nbsp;</p><p class=\"wh-p\">INT（间隔定时器）</p><p class=\"wh-p\">FCS PRIOR（对焦优先）</p><p class=\"wh-p\">AE/AF-L（AE与AF同时锁定）</p><p class=\"wh-p\">PRINT LEVEL（印入光量级别）</p><p class=\"wh-p\">CUSTOM（自定义复位设置）</p><p class=\"wh-p\">闪光灯曝光补偿</p><p class=\"wh-p\">2) 按下&lt;FUNCTION&gt;按钮，可将功能设置后的部分显示画面切换为全显示画面。另外，从部分显示画面到全显示画面的变更，如果 30 秒内不操作 MF-26 的按钮，将自动进行。</p><p class=\"wh-p\">・部分显示画面</p><p class=\"wh-p\">在设置各功能时，为便于操作，将与该功能无关的显示消除的画面。</p><p class=\"wh-p\">・全显示画面</p><p class=\"wh-p\">除设置各功能时的显示画面外，显示所有已设置的各种功能的设定显示等必要信息的画面。</p></div></div>", "bodyFormat": "html", "displayTitle": "FUNCTION 按钮"}}}, {"tocLevel": 4, "tocIndex": 3, "searchText": "MODE 按钮 ＜MODE＞按钮，与指令拨盘组合用于选择数据和功能。 1) 用＜FUNCTION＞按钮选择 DATA 模式时，可选择下列数据。 ・城市编号·时差 (CITY) [年 月 日][月 日 年][日 月 年][日 时 分] ・胶片计数数值 (FRM) ·递增计数数值 (UP) ·固定数值 (FIX) ·曝光值 (TIME F) 2) 在竖线部分可选择 N.SEQ（N幅序列）、BKT（AE 和闪光灯包围）、M EXP（多重曝光）、LONG（长时间曝光）中的任一功能。 3) INT（间隔定时器）功能，可选择拍摄开始时刻、间隔时间及重复拍摄次数的设置。", "tocChildCount": 0, "id": "f90j.t018b03", "tocParent": "f90j.t01544a", "strings": {"zh-Hans": {"title": "MODE 按钮", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;MODE&gt;按钮</p><p class=\"wh-p\">与指令拨盘配合，用于选择数据或功能的按钮。</p><p class=\"wh-p\">1) 用&lt;FUNCTION&gt;按钮选择 DATA 模式时，可选择下列数据（<a class=\"wh-link\" href=\"#appendix-imprintable-data\">可印入的数据</a>）。</p><p class=\"wh-p\">・城市编号·时差 (CITY)</p><p class=\"wh-p\">　[年 月 日]</p><p class=\"wh-p\">　[月 日 年]</p><p class=\"wh-p\">　[日 月 年]</p><p class=\"wh-p\">　[日 时 分]</p><p class=\"wh-p\">・胶片计数数值 (FRM)</p><p class=\"wh-p\">・递增计数数值 (UP)</p><p class=\"wh-p\">・固定数值 (FIX)</p><p class=\"wh-p\">・曝光值 (TIME F)</p><p class=\"wh-p\">2) 在竖线部分</p><p class=\"wh-p\">N.SEQ（N幅序列）、BKT（AE 和闪光灯包围曝光）、M EXP（多重曝光）、LONG（长时间曝光）</p><p class=\"wh-p\">可选择其中任一功能。</p><p class=\"wh-p\">3) INT（间隔定时器）功能</p><p class=\"wh-p\">拍摄开始时刻</p><p class=\"wh-p\">间隔时间</p><p class=\"wh-p\">重复拍摄次数</p><p class=\"wh-p\">可选择这些设置。</p><div class=\"wh-block wh-left wh-appendix\" id=\"appendix-imprintable-data\"><p class=\"wh-p wh-procedure-heading\">&lt;可印入的数据&gt;</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">・[年 月 日]</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">・[月 日 年]</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">・[日 月 年]</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">・[日 时 分]</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">・胶片计数数值 (FRM)</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">・递增计数值 (UP)</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">・固定数值 (FIX)</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">・曝光值 (TIME F)</p></div></div></div>", "bodyFormat": "html", "displayTitle": "MODE 按钮"}}}, {"tocLevel": 4, "tocIndex": 4, "searchText": "\"SELECT\"按钮 ＜SELECT＞按钮：与指令拨盘共同使用，在调整各功能的各种数值时，用于选择调整位置（年、月、日等）的按钮。选择后，所选位置的数值将闪烁。", "tocChildCount": 0, "id": "f90j.t018ef9", "tocParent": "f90j.t01544a", "strings": {"zh-Hans": {"title": "\"SELECT\"按钮", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">按钮：与指令拨盘共同使用，在调整各功能的各种数值时，用于选择调整位置（年、月、日等）的按钮。选择后，所选位置的数值将闪烁。</p></div></div>", "bodyFormat": "html", "displayTitle": "\"SELECT\"按钮"}}}, {"tocLevel": 4, "tocIndex": 5, "searchText": "\"ADJUST\"按钮 <ADJUST>按钮：与<SELECT>按钮和指令拨盘配合，用于修正闪烁数值的按钮。", "tocChildCount": 0, "id": "f90j.t018fff", "tocParent": "f90j.t01544a", "strings": {"zh-Hans": {"title": "\"ADJUST\"按钮", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;ADJUST&gt;按钮</p><p class=\"wh-p\">与&lt;SELECT&gt;按钮和指令拨盘配合，用于修正闪烁数值的按钮。</p></div></div>", "bodyFormat": "html", "displayTitle": "\"ADJUST\"按钮"}}}, {"tocLevel": 4, "tocIndex": 6, "searchText": "\"STRAT/STOP\"按钮 ＜START/STOP＞按钮是用于启动和停止INT（间隔定时器）和LONG（长时间曝光）功能的按钮。当这些功能被设定时，按下按钮功能开始运作，再次按下则停止。", "tocChildCount": 0, "id": "f90j.t0190c4", "tocParent": "f90j.t01544a", "strings": {"zh-Hans": {"title": "\"STRAT/STOP\"按钮", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\"><START/STOP>按钮是用于启动和停止INT（间隔定时器）和LONG（长时间曝光）功能的按钮。当这些功能被设定时，按下按钮功能开始运作，再次按下则停止。</p></div></div>", "bodyFormat": "html", "displayTitle": "\"STRAT/STOP\"按钮"}}}, {"tocLevel": 4, "tocIndex": 7, "searchText": "“SET/RESET”按钮 ＜SET/RESET＞按钮 1)用于设置或取消除DATA模式以外的各种功能的按钮。 设定各种功能时，设定指示灯点亮，点亮的相应功能即被设定。再次按下则熄灭，功能被取消。 2)也可用于数据打印的开始与取消。 选择DATA模式时，每按一次 显示点亮/熄灭。显示点亮时进行数据打印。", "tocChildCount": 0, "id": "f90j.t0191e1", "tocParent": "f90j.t01544a", "strings": {"zh-Hans": {"title": "“SET/RESET”按钮", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;SET/RESET&gt;按钮</p><p class=\"wh-p\">1) 用于设置或取消除 DATA 模式以外的各种功能的按钮。</p><p class=\"wh-p\">设定各种功能时，设定显示<img class=\"wh-inline\" src=\"./assets/f90j/38.webp\" alt=\"\"/>或<img class=\"wh-inline\" src=\"./assets/f90j/39.webp\" alt=\"\"/>点亮，点亮的相应功能即被设定。再次按下则熄灭，功能被取消。</p><p class=\"wh-p\">2) 也可用于数据印入的开始与取消。</p><p class=\"wh-p\">选择 DATA 模式时，每按一次 <img class=\"wh-inline\" src=\"./assets/f90j/40.webp\" alt=\"\"/> 显示点亮/熄灭。<img class=\"wh-inline\" src=\"./assets/f90j/40.webp\" alt=\"\"/> 显示点亮时进行数据印入。</p></div></div>", "bodyFormat": "html", "displayTitle": "“SET/RESET”按钮"}}}, {"tocLevel": 4, "tocIndex": 8, "searchText": "\"PRINT\"按钮 ＜PRINT＞按钮 在需要印入数据和取消印入时使用的按钮。无论当前选择了何种功能，按下该按钮都会切换到DATA模式，同时指示灯亮起，进入可以印入数据的模式。在已选择DATA模式的状态下，每按一次按钮， 指示灯亮起/熄灭，可以选择印入/不印入。", "tocChildCount": 0, "id": "f90j.t019491", "tocParent": "f90j.t01544a", "strings": {"zh-Hans": {"title": "\"PRINT\"按钮", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;PRINT&gt;按钮</p><p class=\"wh-p\">&lt;PRINT&gt;按钮在需要印入数据和取消印入时使用的按钮。</p><p class=\"wh-p\">无论当前选择了何种功能，按下该按钮都会切换到 DATA 模式，同时<img class=\"wh-inline\" src=\"./assets/f90j/40.webp\" alt=\"\"/>显示点亮，进入可以印入数据的模式。</p><p class=\"wh-p\">在已选择 DATA 模式的状态下，每按一次按钮，<img class=\"wh-inline\" src=\"./assets/f90j/40.webp\" alt=\"\"/>显示点亮/熄灭，可以选择印入/不印入。</p></div></div>", "bodyFormat": "html", "displayTitle": "\"PRINT\"按钮"}}}, {"tocLevel": 3, "tocIndex": 1, "searchText": "MF-26-基本设置 多功能控制后背 MF-26 - 基本设置 城市编号选择 年月日、时间设置", "tocChildCount": 2, "id": "f90j.t01962d", "tocParent": "f90j.t01534a", "strings": {"zh-Hans": {"title": "MF-26-基本设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">MF-26-基本设置</p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0196c7\">城市编号选择</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t01c419\">日期和时间设置</a></p></div></div>", "bodyFormat": "html", "displayTitle": "MF-26-基本设置"}}}, {"tocLevel": 4, "tocIndex": 0, "searchText": "城市编号选择 ＜城市号码的选择＞全世界按时差分为24个区域，各时区代表性城市赋予号码即为城市号码。根据旅行目的地选择相应城市号码，时差将自动修正。装入电池时默认选择城市号码20（TOKYO）。 ①使用<FUNCTION>按钮和指令拨盘，将功能选择显示点亮在DATA旁边。 ②使用<MODE>按钮和指令拨盘，点亮城市号码显示“CITY”及“城市号码与时差”。 ③使用<SELECT>按钮和指令拨盘使“城市号码”数值闪烁，再用<ADJUST>按钮和指令拨盘选择所需城市号码。 ④设置夏令时，使用<SELECT>按钮和指令拨盘使“SU”字符闪烁，再用<ADJUST>按钮和指令拨盘点亮夏令时显示。 ⑤使用<SELECT>按钮和指令拨盘将“城市号码”数值恢复常亮状态。 ⑥按下<FUNCTION>按钮，从部分显示画面切换至全显示画面。", "tocChildCount": 0, "id": "f90j.t0196c7", "tocParent": "f90j.t01962d", "strings": {"zh-Hans": {"title": "城市编号选择", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;城市编号选择&gt;</p><p class=\"wh-p\">全世界按时差分为 24 个区域，各时区代表性城市赋予号码即为城市号码。根据旅行目的地选择相应城市号码，时差将自动修正。</p><p class=\"wh-p\">装入电池时默认选择城市号码 20（TOKYO）。</p><p class=\"wh-p\">① 使用&lt;FUNCTION&gt;按钮并转动指令拨盘，使功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>在 DATA 旁点亮。</p><p class=\"wh-p\">② 使用&lt;MODE&gt;按钮和指令拨盘，点亮城市号码显示“CITY”及“城市号码与时差”。</p><p class=\"wh-p\">③ 使用&lt;SELECT&gt;按钮和指令拨盘使“城市号码”数值闪烁，再用&lt;ADJUST&gt;按钮和指令拨盘选择所需城市号码。</p><p class=\"wh-p\">④ 设置夏令时时，使用&lt;SELECT&gt;按钮和指令拨盘使“SU”字符闪烁，再用&lt;ADJUST&gt;按钮和指令拨盘点亮夏令时显示<img class=\"wh-inline\" src=\"./assets/f90j/41.webp\" alt=\"\"/>。</p><p class=\"wh-p\">⑤ 使用&lt;SELECT&gt;按钮和指令拨盘将“城市号码”数值恢复常亮状态。</p><p class=\"wh-p\">⑥ 按下&lt;FUNCTION&gt;按钮，从部分显示画面切换至全显示画面。</p></div></div>", "bodyFormat": "html", "displayTitle": "城市编号选择"}}}, {"tocLevel": 4, "tocIndex": 1, "searchText": "日期和时间设置 ＜年月日、时间设置＞ 为了正确运行日期时间打印、世界时钟、间隔定时器等功能，需先为MF-26内置时钟设定正确的日期与时间。若以日本为基准设置年月日和时间，请事先选择城市编号20（TOKYO）。 ① 按住<FUNCTION>按钮并转动指令拨盘，将功能选择显示点亮至DATA旁。 ② 按住<MODE>按钮并转动指令拨盘，使“年月日”数值显示点亮。（在“月日年”“日月年”模式下也可同样操作设置。） ③ 按住<SELECT>按钮并转动指令拨盘使“年”数值闪烁，再按住<ADJUST>按钮并转动指令拨盘设置“年”。 ④ 同样设置“月”“日”后，按住<SELECT>按钮并转动指令拨盘，使“年月日”全部显示为点亮状态。 ⑤ 按住<MODE>按钮并转动指令拨盘，点亮“日时分”显示，同理设置“时”“分”。 ⑥ 按下<FUNCTION>按钮，从部分显示画面切换至全显示画面。", "tocChildCount": 0, "id": "f90j.t01c419", "tocParent": "f90j.t01962d", "strings": {"zh-Hans": {"title": "日期和时间设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;日期和时间设置&gt;</p><p class=\"wh-p\">为了正确运行日期时间印入、世界时钟、间隔定时器等功能，需先为 MF-26 内置时钟设定正确的日期与时间。</p><p class=\"wh-p\">若以日本为基准设置年月日和时间，请事先选择城市编号 20（TOKYO）。</p><p class=\"wh-p\">① 按住&lt;FUNCTION&gt;按钮并转动指令拨盘，使功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>在 DATA 旁点亮。</p><p class=\"wh-p\">② 按住&lt;MODE&gt;按钮并转动指令拨盘，使“年月日”数值显示点亮。（在“月日年”“日月年”模式下也可同样操作设置。）</p><p class=\"wh-p\">③ 按住&lt;SELECT&gt;按钮并转动指令拨盘使“年”数值闪烁，再按住&lt;ADJUST&gt;按钮并转动指令拨盘设置“年”。</p><p class=\"wh-p\">④ 同样设置“月”“日”后，按住&lt;SELECT&gt;按钮并转动指令拨盘，使“年月日”全部显示为点亮状态。</p><p class=\"wh-p\">⑤ 按住&lt;MODE&gt;按钮并转动指令拨盘，点亮“日 时 分”显示，以同样操作设置“时”“分”。</p><p class=\"wh-p\">⑥ 按下&lt;FUNCTION&gt;按钮，从部分显示画面切换至全显示画面。</p></div></div>", "bodyFormat": "html", "displayTitle": "日期和时间设置"}}}, {"tocLevel": 3, "tocIndex": 2, "searchText": "MF-26 数据印刻 多功能控制后背 MF-26 - 数据打印 / 打印数据的种类 数据打印设置 打印亮度说明", "tocChildCount": 3, "id": "f90j.t01c88d", "tocParent": "f90j.t01534a", "strings": {"zh-Hans": {"title": "MF-26 数据印刻", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">MF-26 数据印刻</p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t01c937\">印入数据的种类</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t01ccbd\">数据记录设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t01d482\">关于印入光量</a></p></div></div>", "bodyFormat": "html", "displayTitle": "MF-26 数据印刻"}}}, {"tocLevel": 4, "tocIndex": 0, "searchText": "印入数据的种类 ＜打印数据类型＞MF-26可打印的数据类型如下1～5。 1) [年 月 日]、[月 日 年]、[日 月 年]、[日 时 分]：打印任一日期、时间数据。 2) 胶片计数数值：打印胶片计数器的数值。 3) 递增计数数值：以任意设定的数值为起点，每次按下快门递增1的6位数字将被打印。 4) 固定数值：打印任意设定的固定6位数字。 5) 曝光值：打印拍摄时的快门速度和光圈值数据。", "tocChildCount": 0, "id": "f90j.t01c937", "tocParent": "f90j.t01c88d", "strings": {"zh-Hans": {"title": "印入数据的种类", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;印入数据的种类&gt;</p><p class=\"wh-p\">MF-26 <a class=\"wh-link\" href=\"#appendix-imprintable-data\">可印入的数据</a>类型如下 1～5。</p><p class=\"wh-p\">1) [年 月 日]、[月 日 年]、[日 月 年]、[日 时 分]：印入任一日期、时间数据。</p><p class=\"wh-p\">2) 胶片计数数值：印入胶片计数器的数值。</p><p class=\"wh-p\">3) 递增计数数值：以任意设定的数值为起点，每次按下快门递增 1 的 6 位数字将被印入。</p><p class=\"wh-p\">4) 固定数值：印入任意设定的固定 6 位数字。</p><p class=\"wh-p\">5) 曝光值：印入拍摄时的快门速度和光圈值数据。</p><div class=\"wh-block wh-left wh-appendix\" id=\"appendix-imprintable-data\"><p class=\"wh-p wh-procedure-heading\">&lt;可印入的数据&gt;</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">・[年 月 日]</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">・[月 日 年]</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">・[日 月 年]</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">・[日 时 分]</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">・胶片计数数值 (FRM)</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">・递增计数值 (UP)</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">・固定数值 (FIX)</p><p class=\"wh-p wh-footnote wh-footnote-bullet\">・曝光值 (TIME F)</p></div></div></div>", "bodyFormat": "html", "displayTitle": "印入数据的种类"}}}, {"tocLevel": 4, "tocIndex": 1, "searchText": "数据记录设置 ＜数据写入设置＞对于 MF-26 可写入的数据，除递增计数值和固定数值以外的数据，只需让希望写入的数据显示和指示灯点亮，即可进行数据写入。要写入递增计数值和固定数值时，则需在显示相应模式的状态下进行数值设定操作。 ①使用＜FUNCTION＞按钮和指令拨盘，使功能选择显示在 DATA 旁边点亮。 ②使用＜MODE＞按钮和指令拨盘，在显示面板上点亮所要写入的数据。 在日期、时间以外的模式下，会显示如下缩写。 胶片计数数值:FRM 递增计数值 :UP 固定数值 :FIX 曝光值 :TIME F 要写入递增计数值或固定数值时，请按以下步骤进行数值设定操作，然后再进行③的操作。 使用＜SELECT＞按钮和指令拨盘，使最左边的 1 位数字闪烁，再用＜ADJUST＞按钮和指令拨盘设定所需数值。第 2～6 位的数字也以同样操作进行设定。 ③按下＜PRINT＞按钮，若显示面板上的 显示和 DATA 旁边的设定显示点亮，即可进行数据写入。再次按下＜PRINT＞按钮， 显示和设定显示熄灭，此时不会写入数据。 ＊通过使用尼康 Photo Secretary 的自定义设置，可设定将数据写入到拍摄胶片片头部分第一张画面之前的“0 张数据写入”。写入数据的种类和通常写入时一样可以选择，但如果选择胶片计数数值，则会写入最多 4 位的胶片编号。", "tocChildCount": 0, "id": "f90j.t01ccbd", "tocParent": "f90j.t01c88d", "strings": {"zh-Hans": {"title": "数据记录设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;数据记录设置&gt;</p><p class=\"wh-p\">对于 MF-26 可印入的数据，除递增计数值和固定数值以外的数据，只需让希望印入的数据显示和<img class=\"wh-inline\" src=\"./assets/f90j/40.webp\" alt=\"\"/>显示点亮，即可进行数据印入。</p><p class=\"wh-p\">要印入递增计数值和固定数值时，则需在显示相应模式的状态下进行数值设定操作。</p><p class=\"wh-p\">① 使用&lt;FUNCTION&gt;按钮并转动指令拨盘，使功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>在 DATA 旁点亮。</p><p class=\"wh-p\">② 使用&lt;MODE&gt;按钮和指令拨盘，在显示面板上点亮所要印入的数据。</p><p class=\"wh-p\">在日期、时间以外的模式下，会显示如下缩写。</p><p class=\"wh-p\">胶片计数数值:FRM</p><p class=\"wh-p\">递增计数值 :UP</p><p class=\"wh-p\">固定数值 :FIX</p><p class=\"wh-p\">曝光值 :TIME F</p><p class=\"wh-p\">要印入递增计数值或固定数值时，请按以下步骤进行数值设定操作，然后再进行③的操作。</p><p class=\"wh-p\">使用&lt;SELECT&gt;按钮和指令拨盘，使最左边的 1 位数字闪烁，再用&lt;ADJUST&gt;按钮和指令拨盘设定所需数值。第 2～6 位的数字也以同样操作进行设定。</p><p class=\"wh-p\">③ 按下&lt;PRINT&gt;按钮，若在显示面板上使<img class=\"wh-inline\" src=\"./assets/f90j/40.webp\" alt=\"\"/>显示与 DATA 旁的设定显示<img class=\"wh-inline\" src=\"./assets/f90j/39.webp\" alt=\"\"/>点亮，即可进行数据印入。再次按下&lt;PRINT&gt;按钮，<img class=\"wh-inline\" src=\"./assets/f90j/40.webp\" alt=\"\"/>显示与设定显示熄灭，此时不会印入数据。</p><p class=\"wh-p\">＊通过使用尼康 Photo Secretary 的自定义设置，可设定将数据印入到拍摄胶片片头部分第一张画面之前的“0 张数据印入”。印入数据的种类和通常印入时一样可以选择，但如果选择胶片计数数值，则会印入最多 4 位的胶片编号。</p></div></div>", "bodyFormat": "html", "displayTitle": "数据记录设置"}}}, {"tocLevel": 4, "tocIndex": 2, "searchText": "关于印入光量 ＜关于打印光量＞如果在 PRINT LEVEL 旁显示并点亮“A”，打印光量会根据胶片感光度自动设定，因此即使使用不同感光度的胶片，也无需逐个调整。若不点亮 PRINT LEVEL 旁的设定显示（保持熄灭），“A”便会显示。 手动设定打印光量时，请按以下步骤操作。 ① 使用＜FUNCTION＞按钮和指令拨盘，点亮 PRINT LEVEL 旁的功能选择显示。 ② 使用＜SELECT＞按钮和指令拨盘，点亮与所用胶片对应的“L、M、H1、H2”其中之一。 ③ 按下＜SET/RESET＞按钮点亮设定显示后，“A”熄灭，设定完成。 ④ 按下＜FUNCTION＞按钮，从部分显示画面切换为全显示画面。", "tocChildCount": 0, "id": "f90j.t01d482", "tocParent": "f90j.t01c88d", "strings": {"zh-Hans": {"title": "关于印入光量", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;关于印入光量&gt;</p><p class=\"wh-p\">如果在 PRINT LEVEL 旁显示并点亮“A”，印入光量会根据胶片感光度自动设定，因此即使使用不同感光度的胶片，也无需逐个调整。</p><p class=\"wh-p\">「A」会在 PRINT LEVEL 旁的设定显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>未点亮（保持熄灭）时显示。</p><p class=\"wh-p\">手动设定印入光量时，请按以下步骤操作。</p><p class=\"wh-p\">① 使用&lt;FUNCTION&gt;按钮并转动指令拨盘，点亮 PRINT LEVEL 旁的功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>。</p><p class=\"wh-p\">② 使用&lt;SELECT&gt;按钮和指令拨盘，点亮与所用胶片对应的「L、M、H1、H2」其中之一。</p><p class=\"wh-p\">③ 按下&lt;SET/RESET&gt;按钮使设定显示<img class=\"wh-inline\" src=\"./assets/f90j/38.webp\" alt=\"\"/>点亮后，「A」熄灭，设定完成。</p><p class=\"wh-p\">④ 按下&lt;FUNCTION&gt;按钮，从部分显示画面切换为全显示画面。</p></div></div>", "bodyFormat": "html", "displayTitle": "关于印入光量"}}}, {"tocLevel": 3, "tocIndex": 3, "searchText": "MF-26-特殊摄影设置 多功能控制后背 MF-26－特殊拍摄设置 N张序列设置 AE包围曝光设置 闪光灯包围曝光设置 多重曝光设置 长时间曝光设置 间隔定时器设置", "tocChildCount": 6, "id": "f90j.t01d809", "tocParent": "f90j.t01534a", "strings": {"zh-Hans": {"title": "MF-26-特殊摄影设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">MF-26-特殊摄影设置</p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0200d9\">N张序列设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0204ad\">AE包围曝光设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t020878\">闪光灯包围曝光设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t020c72\">多重曝光设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t020ff7\">长时间曝光设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t02156b\">间隔定时器设置</a></p></div></div>", "bodyFormat": "html", "displayTitle": "MF-26-特殊摄影设置"}}}, {"tocLevel": 4, "tocIndex": 0, "searchText": "N张序列设置 ＜N张连拍序列设置＞按住快门按钮期间，可连续拍摄设定的张数。N张连拍序列拍摄时，请将相机的胶片过片模式设为连续过片模式。 ①用<FUNCTION>按钮和指令拨盘，使显示面板右侧除DATA、INT之外、由竖线指示的功能名称旁边的功能选择指示灯点亮。（1个点亮，其他3个闪烁） ②用<MODE>按钮和指令拨盘，使N.SEQ旁边的功能选择指示灯点亮。此时，同时点亮“拍摄张数”的数值。 ③用<SELECT>按钮和指令拨盘使“拍摄张数”的数值闪烁，然后用<ADJUST>按钮和指令拨盘设置“拍摄张数”。 ④用<SELECT>按钮和指令拨盘将“拍摄张数”设为点亮状态。 ⑤按下<SET/RESET>按钮，使N.SEQ旁边的设置指示灯点亮即完成设置。 ⑥按下<FUNCTION>按钮，从部分显示画面切换到全显示画面。", "tocChildCount": 0, "id": "f90j.t0200d9", "tocParent": "f90j.t01d809", "strings": {"zh-Hans": {"title": "N张序列设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;N张序列设置&gt;</p><p class=\"wh-p\">按住快门按钮期间，可连续拍摄设定的张数。</p><p class=\"wh-p\">进行 N 张序列拍摄时，请将相机的胶片过片模式设为连续过片模式。</p><p class=\"wh-p\">① 使用&lt;FUNCTION&gt;按钮并转动指令拨盘，使显示面板右侧除 DATA、INT 之外、由竖线指示的功能名称旁的功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>点亮。（1 个点亮，其他 3 个闪烁）</p><p class=\"wh-p\">② 使用&lt;MODE&gt;按钮并转动指令拨盘，使 N.SEQ 旁的功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>点亮。此时，同时点亮「拍摄张数」的数值。</p><p class=\"wh-p\">③ 使用&lt;SELECT&gt;按钮并转动指令拨盘使「拍摄张数」的数值闪烁，然后用&lt;ADJUST&gt;按钮并转动指令拨盘设置「拍摄张数」。</p><p class=\"wh-p\">④ 使用&lt;SELECT&gt;按钮并转动指令拨盘，使「拍摄张数」的数值保持点亮状态。</p><p class=\"wh-p\">⑤ 按下&lt;SET/RESET&gt;按钮，使 N.SEQ 旁的设定显示<img class=\"wh-inline\" src=\"./assets/f90j/39.webp\" alt=\"\"/>点亮即完成设定。</p><p class=\"wh-p\">⑥ 按下&lt;FUNCTION&gt;按钮，从部分显示画面切换为全显示画面。</p></div></div>", "bodyFormat": "html", "displayTitle": "N张序列设置"}}}, {"tocLevel": 4, "tocIndex": 1, "searchText": "AE包围曝光设置 ＜AE包围曝光设置＞通过设定的补偿步长逐步偏移快门速度和光圈值，进行指定张数的拍摄。 ① 使用<FUNCTION>按钮和指令拨盘，在除DATA、INT以外的显示面板右侧竖线指示的功能名称旁，点亮功能选择指示（其中一个点亮，其余三个闪烁）。 ② 使用<MODE>按钮和指令拨盘，在BKT旁点亮功能选择指示及“AE BKT”显示。此时“拍摄张数”和“补偿步长”的数值也会同时点亮。 ③ 使用<SELECT>按钮和指令拨盘使“拍摄张数”数值闪烁，再用<ADJUST>按钮和指令拨盘设定“拍摄张数”。以同样操作设定“补偿步长”。 ④ 使用<SELECT>按钮和指令拨盘，将“拍摄张数”和“补偿步长”的数值改为点亮状态。 ⑤ 按下<SET/RESET>按钮，使BKT旁的设定指示点亮，设定完成。 ⑥ 按下<FUNCTION>按钮，从部分显示画面切换至全屏显示画面。", "tocChildCount": 0, "id": "f90j.t0204ad", "tocParent": "f90j.t01d809", "strings": {"zh-Hans": {"title": "AE包围曝光设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;AE包围曝光设置&gt;</p><p class=\"wh-p\">通过设定的补偿步长逐步偏移快门速度和光圈值，进行指定张数的拍摄。</p><p class=\"wh-p\">① 使用&lt;FUNCTION&gt;按钮并转动指令拨盘，使显示面板右侧除 DATA、INT 之外、由竖线指示的功能名称旁的功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>点亮。（1 个点亮，其他 3 个闪烁）</p><p class=\"wh-p\">② 使用&lt;MODE&gt;按钮并转动指令拨盘，在 BKT 旁点亮功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>及「AE BKT」显示。此时「拍摄张数」和「补偿步长」的数值也会同时点亮。</p><p class=\"wh-p\">③ 使用&lt;SELECT&gt;按钮并转动指令拨盘使「拍摄张数」数值闪烁，再用&lt;ADJUST&gt;按钮并转动指令拨盘设定「拍摄张数」。以同样操作设定「补偿步长」。</p><p class=\"wh-p\">④ 使用&lt;SELECT&gt;按钮并转动指令拨盘，将「拍摄张数」和「补偿步长」的数值改为点亮状态。</p><p class=\"wh-p\">⑤ 按下&lt;SET/RESET&gt;按钮，使 BKT 旁的设定显示<img class=\"wh-inline\" src=\"./assets/f90j/39.webp\" alt=\"\"/>点亮即完成设定。</p><p class=\"wh-p\">⑥ 按下&lt;FUNCTION&gt;按钮，从部分显示画面切换为全显示画面。</p></div></div>", "bodyFormat": "html", "displayTitle": "AE包围曝光设置"}}}, {"tocLevel": 4, "tocIndex": 2, "searchText": "闪光灯包围曝光设置 <闪光灯包围曝光设置> TTL自动调光时，仅闪光灯的闪光输出级别按设定的补偿步长逐级偏移，拍摄设定的张数。 ① 按住<FUNCTION>按钮并转动指令拨盘，在除DATA、INT之外的显示屏右侧竖线所示功能名称旁，点亮功能选择指示。（一个点亮，其他三个闪烁） ② 按住<MODE>按钮并转动指令拨盘，点亮BKT旁边的功能选择指示和BKT显示。此时，将同时点亮“拍摄张数”和“补偿步长”的数值。 ③ 按住<SELECT>按钮并转动指令拨盘，使“拍摄张数”数值闪烁，然后按住<ADJUST>按钮并转动指令拨盘，设置“拍摄张数”。用同样操作设置“补偿步长”。 ④ 按住<SELECT>按钮并转动指令拨盘，使“拍摄张数”和“补偿步长”的数值变为点亮状态。 ⑤ 按下<SET/RESET>按钮，点亮BKT旁边的设置指示，完成设置。 ⑥ 按下<FUNCTION>按钮，从部分显示画面切换到全显示画面。", "tocChildCount": 0, "id": "f90j.t020878", "tocParent": "f90j.t01d809", "strings": {"zh-Hans": {"title": "闪光灯包围曝光设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;闪光灯包围曝光设置&gt;</p><p class=\"wh-p\">TTL自动调光时，仅闪光灯的闪光输出级别按设定的补偿步长逐级偏移，进行指定张数的拍摄。</p><p class=\"wh-p\">① 使用&lt;FUNCTION&gt;按钮并转动指令拨盘，使显示面板右侧除 DATA、INT 之外、由竖线指示的功能名称旁的功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>点亮。（1 个点亮，其他 3 个闪烁）</p><p class=\"wh-p\">② 使用&lt;MODE&gt;按钮并转动指令拨盘，在 BKT 旁点亮功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>及<img class=\"wh-inline\" src=\"./assets/f90j/mf26-su.webp\" alt=\"\"/>显示。此时「拍摄张数」和「补偿步长」的数值也会同时点亮。</p><p class=\"wh-p\">③ 使用&lt;SELECT&gt;按钮并转动指令拨盘使「拍摄张数」数值闪烁，再用&lt;ADJUST&gt;按钮并转动指令拨盘设定「拍摄张数」。以同样操作设定「补偿步长」。</p><p class=\"wh-p\">④ 使用&lt;SELECT&gt;按钮并转动指令拨盘，将「拍摄张数」和「补偿步长」的数值改为点亮状态。</p><p class=\"wh-p\">⑤ 按下&lt;SET/RESET&gt;按钮，使 BKT 旁的设定显示<img class=\"wh-inline\" src=\"./assets/f90j/39.webp\" alt=\"\"/>点亮即完成设定。</p><p class=\"wh-p\">⑥ 按下&lt;FUNCTION&gt;按钮，从部分显示画面切换为全显示画面。</p></div></div>", "bodyFormat": "html", "displayTitle": "闪光灯包围曝光设置"}}}, {"tocLevel": 4, "tocIndex": 3, "searchText": "多重曝光设置 ＜多重曝光设置＞可以在胶片的同一画面上按设定的次数进行重叠拍摄。 ① 使用<FUNCTION>按钮和指令拨盘，在显示面板右侧除DATA、INT外由竖线指示的功能名称旁边，点亮功能选择显示。(一个点亮，其他三个闪烁) ② 使用<MODE>按钮和指令拨盘，在M EXP旁边点亮功能选择显示。此时，同时“曝光次数”的数值也点亮。 ③ 使用<SELECT>按钮和指令拨盘使“曝光次数”的数值闪烁，使用<ADJUST>按钮和指令拨盘设置“曝光次数”。 ④ 使用<SELECT>按钮和指令拨盘，将“拍摄次数”的数值置于点亮状态。 ⑤ 按下<SET/RESET>按钮，在M EXP旁边点亮设置显示，即完成设置。 ⑥ 按下<FUNCTION>按钮，从部分显示画面切换为全显示画面。", "tocChildCount": 0, "id": "f90j.t020c72", "tocParent": "f90j.t01d809", "strings": {"zh-Hans": {"title": "多重曝光设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;多重曝光设置&gt;</p><p class=\"wh-p\">可以在胶片的同一画面上，按设定的次数重叠拍摄。</p><p class=\"wh-p\">① 使用&lt;FUNCTION&gt;按钮并转动指令拨盘，使显示面板右侧除 DATA、INT 之外、由竖线指示的功能名称旁的功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>点亮。（1 个点亮，其他 3 个闪烁）</p><p class=\"wh-p\">② 使用&lt;MODE&gt;按钮并转动指令拨盘，使 M EXP 旁的功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>点亮。此时，「曝光次数」的数值也会同时点亮。</p><p class=\"wh-p\">③ 使用&lt;SELECT&gt;按钮并转动指令拨盘使「曝光次数」的数值闪烁，再用&lt;ADJUST&gt;按钮并转动指令拨盘设定「曝光次数」。</p><p class=\"wh-p\">④ 使用&lt;SELECT&gt;按钮并转动指令拨盘，将「拍摄次数」的数值置于点亮状态。</p><p class=\"wh-p\">⑤ 按下&lt;SET/RESET&gt;按钮，使 M EXP 旁的设定显示<img class=\"wh-inline\" src=\"./assets/f90j/39.webp\" alt=\"\"/>点亮即完成设定。</p><p class=\"wh-p\">⑥ 按下&lt;FUNCTION&gt;按钮，从部分显示画面切换为全显示画面。</p></div></div>", "bodyFormat": "html", "displayTitle": "多重曝光设置"}}}, {"tocLevel": 4, "tocIndex": 4, "searchText": "长时间曝光设置 ＜长时间曝光设置＞长时间曝光拍摄时，可控制快门的开启时间（曝光时间）。 1) 相机侧的设置 将相机的曝光模式设为手动（M），并将快门速度设为“buLb”。 2) MF-26的设置 ① 使用<FUNCTION>按钮和指令拨盘，在显示面板右侧以竖线指示的功能名称旁（除DATA、INT外），点亮功能选择指示。（1个点亮，其他3个闪烁） ② 使用<MODE>按钮和指令拨盘，在LONG旁点亮功能选择指示。此时，同时也会点亮“时:分 秒”显示。 ③ 使用<SELECT>按钮和指令拨盘，按“时”、“分”、“秒”的顺序使显示闪烁，然后用<ADJUST>按钮和指令拨盘依次设置曝光时间。 ④ 使用<SELECT>按钮和指令拨盘，使“时:分 秒”的显示呈点亮状态。 ⑤ 按<SET/RESET>按钮，在LONG旁点亮设置指示，设置即完成。 ⑥ 按<FUNCTION>按钮，从部分显示画面切换至全显示画面。 3) 开始操作，按相机的释放按钮或<START/STOP>按钮。 另外，为了防止抖动，也可使用自拍定时器或遥控线开始操作。", "tocChildCount": 0, "id": "f90j.t020ff7", "tocParent": "f90j.t01d809", "strings": {"zh-Hans": {"title": "长时间曝光设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;长时间曝光设置&gt;</p><p class=\"wh-p\">长时间曝光拍摄时，可控制快门开启时间（曝光时间）。</p><p class=\"wh-p\">1) 相机侧设置</p><p class=\"wh-p\">将相机曝光模式设为手动（M），快门速度设为「buLb」。</p><p class=\"wh-p\">2) MF-26 设置</p><p class=\"wh-p\">① 使用&lt;FUNCTION&gt;按钮并转动指令拨盘，使显示面板右侧除 DATA、INT 之外、由竖线指示的功能名称旁的功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>点亮。（1 个点亮，其他 3 个闪烁）</p><p class=\"wh-p\">② 使用&lt;MODE&gt;按钮并转动指令拨盘，使 LONG 旁的功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>点亮。此时，「时:分 秒」显示也会同时点亮。</p><p class=\"wh-p\">③ 使用&lt;SELECT&gt;按钮并转动指令拨盘，按「时」「分」「秒」顺序使显示闪烁，再用&lt;ADJUST&gt;按钮并转动指令拨盘依次设定曝光时间。</p><p class=\"wh-p\">④ 使用&lt;SELECT&gt;按钮并转动指令拨盘，使「时:分 秒」显示保持点亮状态。</p><p class=\"wh-p\">⑤ 按下&lt;SET/RESET&gt;按钮，使 LONG 旁的设定显示<img class=\"wh-inline\" src=\"./assets/f90j/39.webp\" alt=\"\"/>点亮即完成设定。</p><p class=\"wh-p\">⑥ 按下&lt;FUNCTION&gt;按钮，从部分显示画面切换为全显示画面。</p><p class=\"wh-p\">3) 启动操作为按下相机的释放按钮或&lt;START/STOP&gt;按钮。</p><p class=\"wh-p\">也可使用自拍定时器或遥控线启动，以防止相机抖动。</p></div></div>", "bodyFormat": "html", "displayTitle": "长时间曝光设置"}}}, {"tocLevel": 4, "tocIndex": 5, "searchText": "间隔定时器设置 <间隔定时器的设置>从设定的拍摄开始时间起，每隔一定时间进行1张拍摄，可任意次数重复。另外，如果同时使用N帧序列功能，还可以每隔一定时间拍摄指定张数的连拍。[设置项目] 拍摄开始时间 :日 时 分 间隔时间:99小时59分59秒以内 重复次数 :1次-99次 1) 间隔定时器功能的选择 使用<FUNCTION>按钮和指令拨盘，点亮INT旁边的功能选择显示。 2) 拍摄开始时间的设置 ① 使用<MODE>按钮和指令拨盘，点亮“日 时:分”的数值和开始时间“ST TIME”显示。 ② 使用<SELECT>按钮和指令拨盘，使拍摄开始的“日”数值闪烁，然后使用<ADJUST>按钮和指令拨盘设置“日”。以同样操作，设置拍摄开始时间的“时”和“分”。 ③ 使用<SELECT>按钮和指令拨盘，使“日 时:分”的数值恢复点亮状态。 ＊ 如果不设置“日”，将设定部分设为“--”，然后按下<START/STOP>按钮开始间隔定时器功能，此时会进行第1次拍摄。“--”位于“日”的“31”和“1”之间。 3) 间隔时间的设置 ① 使用<MODE>按钮和指令拨盘，点亮间隔时间“INT TIME”显示和间隔时间的“时:分 秒”数值。 ② 使用<SELECT>按钮和指令拨盘使“时”数值闪烁，使用<ADJUST>按钮和指令拨盘设置“时”。以同样操作设置间隔时间的“分”和“秒”。 ③ 使用<SELECT>按钮和指令拨盘，使“时:分 秒”的数值恢复点亮状态。 4) 重复次数的设置 ① 使用<MODE>按钮和指令拨盘，点亮重复次数“TIME FRM”显示和“重复次数”的数值。 ② 使用<SELECT>按钮和指令拨盘使“重复次数”的数值闪烁，使用<ADJUST>按钮和指令拨盘进行设置。 ③ 使用<SELECT>按钮和指令拨盘，使“重复次数”的数值恢复点亮状态。 ＊ “TIME=次数”/“FRM=张数”会联动显示相同数值。当每次拍摄多张时，请与N帧序列(N.SEQ)功能复合设置。 5) 功能的设置 按下<SET/RESET>按钮，点亮INT旁边的设置显示。 6) 更改为全屏显示画面 按下<FUNCTION>按钮，从部分显示画面切换到全屏显示画面。 7) 功能的启动 按下<START/STOP>按钮，“间隔定时器功能”开始工作。要停止时，再次按下<START/STOP>按钮。", "tocChildCount": 0, "id": "f90j.t02156b", "tocParent": "f90j.t01d809", "strings": {"zh-Hans": {"title": "间隔定时器设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;间隔定时器设置&gt;</p><p class=\"wh-p\">从设定的拍摄开始时间起，每隔一定时间进行1张拍摄，可任意次数重复。另外，如果同时使用N张序列功能，还可以每隔一定时间拍摄指定张数的连拍。</p><p class=\"wh-p\">[设置项目]</p><p class=\"wh-p\">拍摄开始时间：日 时 分</p><p class=\"wh-p\">间隔时间：99小时59分59秒以内</p><p class=\"wh-p\">重复次数：1次–99次</p><p class=\"wh-p\">1) 间隔定时器功能的选择</p><p class=\"wh-p\">使用&lt;FUNCTION&gt;按钮并转动指令拨盘，点亮 INT 旁的功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>。</p><p class=\"wh-p\">2) 拍摄开始时间的设置</p><p class=\"wh-p\">① 使用&lt;MODE&gt;按钮并转动指令拨盘，点亮「日 时:分」的数值和开始时间「ST TIME」显示。</p><p class=\"wh-p\">② 使用&lt;SELECT&gt;按钮并转动指令拨盘，使拍摄开始的「日」数值闪烁，再用&lt;ADJUST&gt;按钮并转动指令拨盘设定「日」。以同样操作设定拍摄开始时间的「时」和「分」。</p><p class=\"wh-p\">③ 使用&lt;SELECT&gt;按钮并转动指令拨盘，使「日 时:分」的数值保持点亮状态。</p><p class=\"wh-p\">＊ 若不设定「日」而将设定部分设为「--」，然后按下&lt;START/STOP&gt;按钮启动间隔定时器功能，则会在该时点进行第1次拍摄。「--」位于「日」的「31」与「1」之间。</p><p class=\"wh-p\">3) 间隔时间的设置</p><p class=\"wh-p\">① 使用&lt;MODE&gt;按钮并转动指令拨盘，点亮间隔时间「INT TIME」显示和间隔时间的「时:分 秒」数值。</p><p class=\"wh-p\">② 使用&lt;SELECT&gt;按钮并转动指令拨盘使「时」数值闪烁，再用&lt;ADJUST&gt;按钮并转动指令拨盘设定「时」。以同样操作设定间隔时间的「分」和「秒」。</p><p class=\"wh-p\">③ 使用&lt;SELECT&gt;按钮并转动指令拨盘，使「时:分 秒」的数值保持点亮状态。</p><p class=\"wh-p\">4) 重复次数的设置</p><p class=\"wh-p\">① 使用&lt;MODE&gt;按钮并转动指令拨盘，点亮重复次数「TIME FRM」显示和「重复次数」的数值。</p><p class=\"wh-p\">② 使用&lt;SELECT&gt;按钮并转动指令拨盘使「重复次数」的数值闪烁，再用&lt;ADJUST&gt;按钮并转动指令拨盘进行设定。</p><p class=\"wh-p\">③ 使用&lt;SELECT&gt;按钮并转动指令拨盘，使「重复次数」的数值保持点亮状态。</p><p class=\"wh-p\">＊「TIME=次数」/「FRM=张数」会联动显示相同数值。当每次拍摄多张时，请与N张序列(N.SEQ)功能复合设置。</p><p class=\"wh-p\">5) 功能的设置</p><p class=\"wh-p\">按下&lt;SET/RESET&gt;按钮，使 INT 旁的设定显示<img class=\"wh-inline\" src=\"./assets/f90j/39.webp\" alt=\"\"/>点亮。</p><p class=\"wh-p\">6) 更改为全显示画面</p><p class=\"wh-p\">按下&lt;FUNCTION&gt;按钮，从部分显示画面切换为全显示画面。</p><p class=\"wh-p\">7) 功能的启动</p><p class=\"wh-p\">按下&lt;START/STOP&gt;按钮后，「间隔定时器功能」开始工作。要停止时，再次按下&lt;START/STOP&gt;按钮。</p></div></div>", "bodyFormat": "html", "displayTitle": "间隔定时器设置"}}}, {"tocLevel": 3, "tocIndex": 4, "searchText": "闪光曝光补偿设置 ＜闪光补偿设置＞在TTL自动调光拍摄时，可以仅补偿闪光灯的调光级别。 ①按<FUNCTION>按钮并转动指令拨盘，使闪光补偿标记 旁边的功能选择显示点亮。 ②按<SELECT>按钮并转动指令拨盘，使“闪光补偿”数值闪烁，再按<ADJUST>按钮并转动指令拨盘设定数值。 ③按<SELECT>按钮并转动指令拨盘，使“闪光补偿”数值变为点亮状态。 ④按下<SET/RESET>按钮，使闪光补偿标记 旁边的设定显示点亮，即完成设定。 ⑤按下<FUNCTION>按钮，从部分显示画面切换到全显示画面。", "tocChildCount": 0, "id": "f90j.t02447c", "tocParent": "f90j.t01534a", "strings": {"zh-Hans": {"title": "闪光曝光补偿设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;闪光曝光补偿设置&gt;</p><p class=\"wh-p\">在 TTL 自动调光拍摄时，可以仅补偿闪光灯的调光级别。</p><p class=\"wh-p\">① 使用&lt;FUNCTION&gt;按钮并转动指令拨盘，使闪光曝光补偿标记<img class=\"wh-inline\" src=\"./assets/f90j/42.webp\" alt=\"\"/>旁的功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>点亮。</p><p class=\"wh-p\">② 使用&lt;SELECT&gt;按钮并转动指令拨盘使「闪光曝光补偿」数值闪烁，再用&lt;ADJUST&gt;按钮并转动指令拨盘设定数值。</p><p class=\"wh-p\">③ 使用&lt;SELECT&gt;按钮并转动指令拨盘，使「闪光曝光补偿」数值保持点亮状态。</p><p class=\"wh-p\">④ 按下&lt;SET/RESET&gt;按钮，使闪光曝光补偿标记<img class=\"wh-inline\" src=\"./assets/f90j/42.webp\" alt=\"\"/>旁的设定显示<img class=\"wh-inline\" src=\"./assets/f90j/38.webp\" alt=\"\"/>点亮，即完成设定。</p><p class=\"wh-p\">⑤ 按下&lt;FUNCTION&gt;按钮，从部分显示画面切换为全显示画面。</p></div></div>", "bodyFormat": "html", "displayTitle": "闪光曝光补偿设置"}}}, {"tocLevel": 3, "tocIndex": 5, "searchText": "MF-26 自定义功能设置 多功能控制后背 MF-26-自定义功能设置 AE和AF同时锁定设置 对焦优先设置 自定义复位设置", "tocChildCount": 3, "id": "f90j.t02479a", "tocParent": "f90j.t01534a", "strings": {"zh-Hans": {"title": "MF-26 自定义功能设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">MF-26 自定义功能设置</p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t024882\">AE与AF同时锁定设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0249f8\">对焦优先设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t024c68\">自定义复位的设置</a></p></div></div>", "bodyFormat": "html", "displayTitle": "MF-26 自定义功能设置"}}}, {"tocLevel": 4, "tocIndex": 0, "searchText": "AE与AF同时锁定设置 ＜AE和AF同时锁定设置＞通过操作AE锁定杆或AF锁定按钮中的任意一个，可以同时锁定AE和AF。 ①按<FUNCTION>按钮并转动指令拨盘，点亮AE/AF-L旁边的功能选择显示。②按<SET/RESET>按钮，点亮AE/AF-L旁边的设置显示即完成设置。③按<FUNCTION>按钮，从部分显示画面切换到全屏显示画面。", "tocChildCount": 0, "id": "f90j.t024882", "tocParent": "f90j.t02479a", "strings": {"zh-Hans": {"title": "AE与AF同时锁定设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;AE与AF同时锁定设置&gt;</p><p class=\"wh-p\">通过操作 AE 锁定杆或 AF 锁定按钮中的任意一个，可以同时锁定 AE 和 AF。</p><p class=\"wh-p\">① 使用&lt;FUNCTION&gt;按钮并转动指令拨盘，点亮 AE/AF-L 旁的功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>。</p><p class=\"wh-p\">② 按下&lt;SET/RESET&gt;按钮，使 AE/AF-L 旁的设定显示<img class=\"wh-inline\" src=\"./assets/f90j/38.webp\" alt=\"\"/>点亮，即完成设定。</p><p class=\"wh-p\">③ 按下&lt;FUNCTION&gt;按钮，从部分显示画面切换为全显示画面。</p></div></div>", "bodyFormat": "html", "displayTitle": "AE与AF同时锁定设置"}}}, {"tocLevel": 4, "tocIndex": 1, "searchText": "对焦优先设置 ＜对焦优先设置＞可以将连续AF伺服和手动对焦模式（无论焦点状态如何都可随时释放）设置为只有合焦时才能释放的对焦优先状态。 ①用<FUNCTION>按钮和指令拨盘，使FCS PRIOR旁边的功能选择显示点亮。 ②按下<SET/RESET>按钮，使FCS PRIOR旁边的设置显示点亮即完成设置。 ③按下<FUNCTION>按钮，从部分显示画面切换到全显示画面。", "tocChildCount": 0, "id": "f90j.t0249f8", "tocParent": "f90j.t02479a", "strings": {"zh-Hans": {"title": "对焦优先设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;对焦优先设置&gt;</p><p class=\"wh-p\">可以将连续 AF 伺服和手动对焦模式（无论合焦状态如何都可随时释放快门）设置为仅在合焦时才能释放快门的对焦优先状态。</p><p class=\"wh-p\">① 使用&lt;FUNCTION&gt;按钮并转动指令拨盘，点亮 FCS PRIOR 旁的功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>。</p><p class=\"wh-p\">② 按下&lt;SET/RESET&gt;按钮，使 FCS PRIOR 旁的设定显示<img class=\"wh-inline\" src=\"./assets/f90j/38.webp\" alt=\"\"/>点亮，即完成设定。</p><p class=\"wh-p\">③ 按下&lt;FUNCTION&gt;按钮，从部分显示画面切换为全显示画面。</p></div></div>", "bodyFormat": "html", "displayTitle": "对焦优先设置"}}}, {"tocLevel": 4, "tocIndex": 2, "searchText": "自定义复位的设置 ＜自定义复位设置＞可更改在相机机身上进行两键复位操作时的复位内容，从相机标准设置的即时复位组合改为任意组合。可设定的项目有测光、胶片过片、曝光、闪光同步各模式以及对焦区域。 1)相机端的设置 将相机的测光、胶片过片、曝光、闪光同步、对焦区域各功能设定为想要复位的状态。 2)MF-26的设置 ①使用<FUNCTION>按钮和命令拨盘，点亮CUSTOM旁边的功能选择显示和“CSTM”显示。 ②按下<SET/RESET>按钮，点亮CUSTOM旁边的设定显示后，设置完成。 ③按下<FUNCTION>按钮，从部分显示画面切换到全显示画面。", "tocChildCount": 0, "id": "f90j.t024c68", "tocParent": "f90j.t02479a", "strings": {"zh-Hans": {"title": "自定义复位的设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;自定义复位的设置&gt;</p><p class=\"wh-p\">可更改在相机机身上进行两键复位操作时的复位内容，从相机标准设置的即时复位组合改为任意组合。可设定的项目有测光、胶片过片、曝光、闪光同步各模式以及对焦区域。</p><p class=\"wh-p\">1) 相机端的设置</p><p class=\"wh-p\">将相机的测光、胶片过片、曝光、闪光同步、对焦区域各功能设定为希望复位后的状态。</p><p class=\"wh-p\">2) MF-26 的设置</p><p class=\"wh-p\">① 使用&lt;FUNCTION&gt;按钮并转动指令拨盘，点亮 CUSTOM 旁的功能选择显示<img class=\"wh-inline\" src=\"./assets/f90j/37.webp\" alt=\"\"/>及「CSTM」显示。</p><p class=\"wh-p\">② 按下&lt;SET/RESET&gt;按钮，使 CUSTOM 旁的设定显示<img class=\"wh-inline\" src=\"./assets/f90j/38.webp\" alt=\"\"/>点亮，即完成设定。</p><p class=\"wh-p\">③ 按下&lt;FUNCTION&gt;按钮，从部分显示画面切换为全显示画面。</p></div></div>", "bodyFormat": "html", "displayTitle": "自定义复位的设置"}}}, {"tocLevel": 2, "tocIndex": 1, "searchText": "世界时间数据后背 MF-25 世界时间数据后背 MF-25 城市编号选择 日期设置 时间设置 闹铃设置 数据印入设置", "tocChildCount": 5, "id": "f90j.t024f71", "tocParent": "f90j.t015277", "strings": {"zh-Hans": {"title": "世界时间数据后背 MF-25", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">世界时间数据后背 MF-25</p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t02504c\">选择城市编号</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0251c0\">日期设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0254aa\">时间设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0256f3\">警报设置</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t028347\">数据印入设置</a></p></div></div>", "bodyFormat": "html", "displayTitle": "世界时间数据后背 MF-25"}}}, {"tocLevel": 3, "tocIndex": 0, "searchText": "选择城市编号 ＜城市号码的选择＞按下+和-的<CITY NO.>按钮，在城市号码显示区点亮所需城市的\"城市号码\"，时差将自动修正，并显示所选地区的日期、时间。如要设置夏令时，请按下<夏令时>按钮（与最左边的<ADJUST>按钮共用），在显示面板上点亮夏令时指示。装入电池时，已选择城市号码20（TOKYO）。", "tocChildCount": 0, "id": "f90j.t02504c", "tocParent": "f90j.t024f71", "strings": {"zh-Hans": {"title": "选择城市编号", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;选择城市编号&gt;</p><p class=\"wh-p\">按下 + 和 - 的&lt;CITY NO.&gt;按钮，在城市号码显示区点亮所需城市的「城市号码」，时差将自动修正，并显示所选地区的日期、时间。</p><p class=\"wh-p\">如要设置夏令时，请按下&lt;夏令时&gt;按钮（与最左边的&lt;ADJUST&gt;按钮共用），在显示面板上点亮夏令时显示<img class=\"wh-inline\" src=\"./assets/f90j/41.webp\" alt=\"\"/>。</p><p class=\"wh-p\">装入电池时，已选择城市编号 20（TOKYO）。</p></div></div>", "bodyFormat": "html", "displayTitle": "选择城市编号"}}}, {"tocLevel": 3, "tocIndex": 1, "searchText": "日期设置 ＜日期设置＞ ①按＜MODE＞按钮，点亮“年月日”显示。 ②按＜SET＞按钮使“年月日”数值闪烁，然后按左边的＜ADJUST＞按钮设定“年”。 ③同样，按中间的＜ADJUST＞按钮设定“月”，按右边的＜ADJUST＞按钮设定“日”。 ④按＜SET＞按钮，点亮所设定的“年月日”数值即完成设置。 (月日年、日月年模式也可同样操作设置。)", "tocChildCount": 0, "id": "f90j.t0251c0", "tocParent": "f90j.t024f71", "strings": {"zh-Hans": {"title": "日期设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;日期设置&gt;</p><p class=\"wh-p\">① 按下&lt;MODE&gt;按钮，点亮「年月日」显示。</p><p class=\"wh-p\">② 按下&lt;SET&gt;按钮使「年月日」数值闪烁，然后按左边的&lt;ADJUST&gt;按钮设定「年」。</p><p class=\"wh-p\">③ 同样，按中间的&lt;ADJUST&gt;按钮设定「月」，按右边的&lt;ADJUST&gt;按钮设定「日」。</p><p class=\"wh-p\">④ 按下&lt;SET&gt;按钮，点亮所设定的「年月日」数值即完成设置。</p><p class=\"wh-p\">（月日年、日月年模式也可同样操作设置。）</p></div></div>", "bodyFormat": "html", "displayTitle": "日期设置"}}}, {"tocLevel": 3, "tocIndex": 2, "searchText": "时间设置 ＜时间设置＞ ①按＜MODE＞按钮，点亮“日 时：分”的数值。 ②按＜SET＞按钮，使“日 时：分”的数值闪烁，然后按左侧的＜ADJUST＞按钮设置“日”。 ③同样，按中央的＜ADJUST＞按钮设置“时”，按右侧的＜ADJUST＞按钮设置“分”。 ④按＜SET＞按钮，当“日 时：分”的数值点亮即完成设置。", "tocChildCount": 0, "id": "f90j.t0254aa", "tocParent": "f90j.t024f71", "strings": {"zh-Hans": {"title": "时间设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;时间设置&gt;</p><p class=\"wh-p\">① 按下&lt;MODE&gt;按钮，点亮「日 时：分」的数值。</p><p class=\"wh-p\">② 按下&lt;SET&gt;按钮使「日 时：分」的数值闪烁，然后按左边的&lt;ADJUST&gt;按钮设定「日」。</p><p class=\"wh-p\">③ 同样，按中间的&lt;ADJUST&gt;按钮设定「时」，按右边的&lt;ADJUST&gt;按钮设定「分」。</p><p class=\"wh-p\">④ 按下&lt;SET&gt;按钮，点亮所设定的「日 时：分」数值即完成设置。</p></div></div>", "bodyFormat": "html", "displayTitle": "时间设置"}}}, {"tocLevel": 3, "tocIndex": 3, "searchText": "警报设置 <闹铃设置> 设定时分后，即可在每天同一时间反复响起闹铃。 ①按下<MODE>按钮，显示“AL”。 ②按下<SET>按钮，使“时：分”数值闪烁，然后按中间的<ADJUST>按钮设定“时”。 ③同样地，按下右侧的<ADJUST>按钮设定“分”。 ④按下<SET>按钮，使设定的“时：分”数值常亮，设置完成。 ⑤要启动闹铃，按下<闹铃>按钮（与左侧的<ADJUST>按钮共用），显示面板上的闹铃图标点亮后，即可在每天同一时间响起闹铃。 ⑥闹铃会持续响1分钟，若要在中途停止，请按<闹铃>按钮。", "tocChildCount": 0, "id": "f90j.t0256f3", "tocParent": "f90j.t024f71", "strings": {"zh-Hans": {"title": "警报设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;警报设置&gt;</p><p class=\"wh-p\">设定时分后，即可在每天同一时间反复响起警报。</p><p class=\"wh-p\">① 按下&lt;MODE&gt;按钮，显示「AL」。</p><p class=\"wh-p\">② 按下&lt;SET&gt;按钮使「时：分」数值闪烁，然后按中间的&lt;ADJUST&gt;按钮设定「时」。</p><p class=\"wh-p\">③ 同样，按右边的&lt;ADJUST&gt;按钮设定「分」。</p><p class=\"wh-p\">④ 按下&lt;SET&gt;按钮，点亮所设定的「时：分」数值即完成设置。</p><p class=\"wh-p\">⑤ 要启动警报，请按下&lt;警报&gt;按钮（与左侧的&lt;ADJUST&gt;按钮共用），在显示面板上点亮警报显示<img class=\"wh-inline\" src=\"./assets/f90j/43.webp\" alt=\"\"/>，即可在每天同一时间响起警报。</p><p class=\"wh-p\">⑥ 警报会持续响 1 分钟；若要在中途停止，请按&lt;警报&gt;按钮。</p></div></div>", "bodyFormat": "html", "displayTitle": "警报设置"}}}, {"tocLevel": 3, "tocIndex": 4, "searchText": "数据印入设置 ＜数据写し込みの设定＞MF-25可以写入的数据为［月 日 年］、［日 月 年］、［年 月 日］、［日 时：分］中的任意一种。只需按下＜MODE＞按钮，点亮想要写入的数据和显示，便可进行数据写入。不进行数据写入时，按下＜MODE＞按钮， 关闭显示，显示“-- -- --”。", "tocChildCount": 0, "id": "f90j.t028347", "tocParent": "f90j.t024f71", "strings": {"zh-Hans": {"title": "数据印入设置", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;数据印入设置&gt;</p><p class=\"wh-p\">MF-25可以写入的数据为［月 日 年］、［日 月 年］、［年 月 日］、［日 时：分］中的任意一种。</p><p class=\"wh-p\">只需按下&lt;MODE&gt;按钮，点亮想要写入的数据和<img class=\"wh-inline\" src=\"./assets/f90j/40.webp\" alt=\"\"/>显示，便可进行数据写入。</p><p class=\"wh-p\">不进行数据写入时，按下&lt;MODE&gt;按钮，熄灭<img class=\"wh-inline\" src=\"./assets/f90j/40.webp\" alt=\"\"/>显示，显示「-- -- --」。</p></div></div>", "bodyFormat": "html", "displayTitle": "数据印入设置"}}}, {"tocLevel": 1, "tocIndex": 2, "searchText": "主要配件篇 主要配件篇 闪光灯 SB-26 遥控线 MC-20 遥控组件 ML-3 竖拍手柄 MB-10 E型对焦屏", "tocChildCount": 5, "id": "f90j.t028490", "tocParent": "f90j.t00000c", "strings": {"zh-Hans": {"title": "主要配件篇", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">主要配件篇</p><figure class=\"wh-fig wh-fig-left\"><img src=\"./assets/f90j/44.webp\" alt=\"\"/></figure><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t0285ca\">闪光灯 SB-26</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t02d174\">快门线 MC-20</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t02d4f1\">Modulite遥控套装 ML-3</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t02d7e8\">竖拍手柄 MB-10</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t030043\">E型取景屏</a></p></div></div>", "bodyFormat": "html", "displayTitle": "主要配件篇"}}}, {"tocLevel": 2, "tocIndex": 0, "searchText": "闪光灯 SB-26 スピードライト SB-26 多区域BL调光 红眼减轻发光 FP闪光 后帘同步拍摄 多重闪光拍摄 TTL自动调光不足显示 无线多灯拍摄", "tocChildCount": 7, "id": "f90j.t0285ca", "tocParent": "f90j.t028490", "strings": {"zh-Hans": {"title": "闪光灯 SB-26", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">闪光灯 SB-26</p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t028714\">多区域BL调光</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t028d34\">防红眼闪光</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t02903b\">FP高速同步</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t029625\">后帘同步拍摄</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t02c407\">多重闪光拍摄</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t02cab4\">TTL 自动调光欠曝指示</a></p><p class=\"wh-p wh-menu-row\"><a class=\"wh-link\" href=\"#topic/f90j.t02ccac\">无线多灯拍摄</a></p></div></div>", "bodyFormat": "html", "displayTitle": "闪光灯 SB-26"}}}, {"tocLevel": 3, "tocIndex": 0, "searchText": "多区域BL调光 ＜多重区域BL调光＞相机拥有5分区TTL自动调光传感器，在闪光灯拍摄中进一步提升调光精度。特别是当组合使用SB-26和D型镜头时，会在快门帘即将打开前进行监视预闪，结合镜头的距离信号，瞬间判断被摄体状况，对被摄主体和背景都给予更合适的曝光，实现“3D-多重区域BL调光”。[操作方法] ①安装CPU内置尼克尔镜头。 ＊根据所装镜头，形成以下多重区域BL调光。 安装D型AF镜头时 具备距离信号和监视预闪的“3D-多重区域BL调光” 安装非D型AF镜头/Ai-P镜头时 具备监视预闪的“多重区域BL调光” ②将曝光模式和测光模式设定为任意模式。 ③将SB-26的＜模式选择器＞设定为TTL。 ④确认SB-26的多重区域BL调光指示灯点亮。 如果熄灭，请按＜M＞按钮将其点亮。 ⑤确认调光范围与拍摄距离的关系等进行拍摄。", "tocChildCount": 0, "id": "f90j.t028714", "tocParent": "f90j.t0285ca", "strings": {"zh-Hans": {"title": "多区域BL调光", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;多区域BL调光&gt;</p><p class=\"wh-p\">相机配备 5 分区 TTL 自动调光传感器，在闪光灯拍摄中可进一步提高调光精度。</p><p class=\"wh-p\">特别是配合 SB-26 与 D 型镜头使用时，会在快门帘开启前瞬间发出监视预闪，并结合镜头距离信号判断被摄体情况，可对主要被摄体与背景同时给出更合适的曝光，实现「3D-多区域BL调光」。</p><p class=\"wh-p wh-procedure-heading\">[操作方法]</p><p class=\"wh-p\">① 安装内置 CPU 的尼克尔镜头。</p><p class=\"wh-p wh-footnote\">＊根据所装镜头，将形成以下多区域 BL 调光。</p><p class=\"wh-p wh-procedure-indent\">D 型 AF 镜头安装时</p><p class=\"wh-p wh-procedure-indent\">具备距离信号与监视预闪的「3D-多区域BL调光」</p><p class=\"wh-p wh-procedure-indent\">D 型以外的 AF 镜头 / Ai-P 镜头安装时</p><p class=\"wh-p wh-procedure-indent\">具备监视预闪的「多区域BL调光」</p><p class=\"wh-p\">② 将曝光模式与测光模式设为任意模式。</p><p class=\"wh-p\">③ 将 SB-26 的 &lt;模式选择器&gt; 设为 TTL。</p><p class=\"wh-p\">④ 确认 SB-26 的多区域 BL 调光显示已点亮。</p><p class=\"wh-p wh-procedure-indent\">若已熄灭，请按 &lt;M&gt; 按钮将其点亮。</p><p class=\"wh-p\">⑤ 确认调光范围与拍摄距离的关系等后进行拍摄。</p></div></div>", "bodyFormat": "html", "displayTitle": "多区域BL调光"}}}, {"tocLevel": 3, "tocIndex": 1, "searchText": "防红眼闪光 ＜红眼减轻发光＞相机与SB-26配合使用时，通过在释放快门前进行预闪灯照射，可以减轻人物被摄体的红眼现象，实现“红眼减轻发光”。[操作方法] ①将相机的闪光同步模式设置为红眼减轻发光模式，或选择rE（红眼减轻）模式。 ＊通过以上设置，无论SB-26的<闪光同步选择器（前帘，后帘）>如何设定，都将自动设定为前帘同步拍摄。 ②按下快门按钮后，先进行红眼减轻的预闪灯照射，然后快门释放并进行主闪光。", "tocChildCount": 0, "id": "f90j.t028d34", "tocParent": "f90j.t0285ca", "strings": {"zh-Hans": {"title": "防红眼闪光", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;防红眼闪光&gt;</p><p class=\"wh-p\">相机与 SB-26 配合使用时，通过在释放快门前进行预闪灯照射，可以减轻人物被摄体的红眼现象，实现「防红眼闪光」。</p><p class=\"wh-p wh-procedure-heading\">[操作方法]</p><p class=\"wh-p\">① 将相机的闪光同步模式设为防红眼闪光模式，或选择 rE（红眼减轻）模式。</p><p class=\"wh-p wh-footnote\">＊通过以上设置，无论 SB-26 的 &lt;闪光同步选择器（NORMAL、REAR）&gt; 如何设定，都将自动设定为前帘同步拍摄。</p><p class=\"wh-p\">② 按下快门按钮后，先进行防红眼预闪灯照射，然后快门释放并进行主闪光。</p></div></div>", "bodyFormat": "html", "displayTitle": "防红眼闪光"}}}, {"tocLevel": 3, "tocIndex": 2, "searchText": "FP高速同步 ＜FP发光＞相机与SB-26组合时，可实现FP发光。可使用1/4000秒～1/250秒的高速快门速度进行闪光拍摄，因此大大扩展了日光同步拍摄时的拍摄领域。[操作方法] ①将相机的曝光模式设为手动(M)。 ②将SB-26的<模式选择器>设为手动模式(M)。 ③按下SB-26的<M>按钮，选择FP1或FP2。 每按一次<M>按钮，输出光量显示会变化为1/1、1/2、1/4……1/64、1、2。显示的1表示“FP1”，显示的2表示“FP2”。“FP1”的输出光量(GN)比“FP2”大，因此当到被摄体的拍摄距离较长时推荐使用，“FP2”输出光量较小，因此当拍摄距离较短时推荐使用。 ④将快门速度设定为1/4000秒～1/250秒。 ＊设定的快门速度每提高2档，闪光指数变为1/2。＊不建议设定1/8000秒以及1/125秒以下的低速度快门，因为缝隙的关系可能导致曝光不均匀。 ⑤参考SB-26的条形显示和取景器内的曝光指示器设定光圈值。 ⑥参考SB-26的条形显示，调节拍摄距离进行拍摄。", "tocChildCount": 0, "id": "f90j.t02903b", "tocParent": "f90j.t0285ca", "strings": {"zh-Hans": {"title": "FP高速同步", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;FP高速同步&gt;</p><p class=\"wh-p\">相机与 SB-26 组合时，可实现 FP 高速同步闪光。可使用 1/4000 秒～1/250 秒的高速快门速度进行闪光拍摄，因此大大扩展了日光同步拍摄时的拍摄范围。</p><p class=\"wh-p wh-procedure-heading\">[操作方法]</p><p class=\"wh-p\">① 将相机的曝光模式设为手动（M）。</p><p class=\"wh-p\">② 将 SB-26 的 &lt;模式选择器&gt; 设为手动模式（M）。</p><p class=\"wh-p\">③ 按下 SB-26 的 &lt;M&gt; 按钮，选择 FP1 或 FP2。</p><p class=\"wh-p wh-procedure-indent\">每按一次 &lt;M&gt; 按钮，输出光量显示会变化为 1/1、1/2、1/4……1/64、1、2。显示的 1 表示「FP1」，显示的 2 表示「FP2」。「FP1」的输出光量（GN）比「FP2」大，因此被摄体距离较远时推荐使用；「FP2」输出光量较小，拍摄距离较近时推荐使用。</p><p class=\"wh-p\">④ 将快门速度设定为 1/4000 秒～1/250 秒。</p><p class=\"wh-p wh-footnote\">＊设定的快门速度每提高 2 档，闪光指数变为 1/2。</p><p class=\"wh-p wh-footnote\">＊不建议设定 1/8000 秒以及 1/125 秒以下的低速度快门，因为缝隙的关系可能导致曝光不均匀。</p><p class=\"wh-p\">⑤ 参考 SB-26 的条形显示和取景器内的曝光指示器设定光圈值。</p><p class=\"wh-p\">⑥ 参考 SB-26 的条形显示，调节拍摄距离进行拍摄。</p></div></div>", "bodyFormat": "html", "displayTitle": "FP高速同步"}}}, {"tocLevel": 3, "tocIndex": 3, "searchText": "后帘同步拍摄 <后帘同步拍摄>当相机与SB-26组合时，将SB-26的<同步选择器>设为REAR即可设置后帘同步拍摄。[操作方法] ①将SB-26的<模式选择器>设为TTL、A、M中的任一种。 ②将SB-26的<同步选择器>设为REAR。 ③将相机的闪光同步模式设为除红眼减轻闪光模式以外时，相机的同步模式显示部会显示REAR（曝光模式为P、A时显示REAR和SLOW）。 ＊即使使用闪光灯上没有后帘同步切换开关的闪光灯，相机也可进行后帘同步拍摄。这种情况下，请在相机侧将同步模式设为REAR。 ④决定适当的快门速度和光圈进行拍摄。 ＊后帘同步拍摄与低速快门组合效果更佳。 因此，曝光模式推荐可使用自由快门速度的S或M。Ps模式无法使用。", "tocChildCount": 0, "id": "f90j.t029625", "tocParent": "f90j.t0285ca", "strings": {"zh-Hans": {"title": "后帘同步拍摄", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;后帘同步拍摄&gt;</p><p class=\"wh-p\">当相机与 SB-26 组合时，将 SB-26 的 &lt;同步选择器&gt; 设为 REAR，即可进行后帘同步拍摄。</p><p class=\"wh-p wh-procedure-heading\">[操作方法]</p><p class=\"wh-p\">① 将 SB-26 的 &lt;模式选择器&gt; 设为 TTL、A、M 中的任一种。</p><p class=\"wh-p\">② 将 SB-26 的 &lt;同步选择器&gt; 设为 REAR。</p><p class=\"wh-p\">③ 将相机的闪光同步模式设为防红眼闪光模式以外时，相机的同步模式显示部会显示 REAR（曝光模式为 P、A 时显示 REAR 和 SLOW）。</p><p class=\"wh-p wh-footnote\">＊即使使用闪光灯上没有后帘同步切换开关的闪光灯，相机也可进行后帘同步拍摄。这种情况下，请在相机侧将同步模式设为 REAR。</p><p class=\"wh-p\">④ 决定适当的快门速度和光圈进行拍摄。</p><p class=\"wh-p wh-footnote\">＊后帘同步拍摄与低速快门组合效果更佳。</p><p class=\"wh-p wh-procedure-indent\">因此，曝光模式推荐使用可自由设定快门速度的 S 或 M。Ps 模式无法使用。</p></div></div>", "bodyFormat": "html", "displayTitle": "后帘同步拍摄"}}}, {"tocLevel": 3, "tocIndex": 4, "searchText": "多重闪光拍摄 ＜多重闪光拍摄＞SB-26的多重闪光模式是在相机快门打开期间，以设定的恒定发光量的闪光，按照设定的发光间隔和发光次数重复发光的模式。[操作方法] ①将相机的曝光模式设为手动（M）。 ②将SB-26的＜模式选择器＞设为多重闪光模式。 ③将SB-26的＜同步选择器＞设为NORMAL。 ④按下SB-26的＜M＞按钮，设置发光量。 ＊发光量可设定为1/8、1/16、1/32、1/64之一。 ⑤操作SB-26的＜SEL＞按钮和＜▲＞或＜▼＞按钮，设置发光间隔（频率Hz）和发光次数（重复次数）。 ＊发光次数受所设定的发光间隔和发光量限制，无法设定超过限制的次数。 ⑥设置相机的快门速度。 ＊多重闪光拍摄时，快门需保持打开直至所有按设定的发光间隔和发光次数的闪光完成，快门速度以“发光次数÷发光间隔（Hz）”秒为参考，设为该值或更低。 ⑦参考SB-26的指示条显示，设定光圈值进行拍摄。 ＊多重闪光拍摄时为防止手抖，建议使用三脚架。", "tocChildCount": 0, "id": "f90j.t02c407", "tocParent": "f90j.t0285ca", "strings": {"zh-Hans": {"title": "多重闪光拍摄", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;多重闪光拍摄&gt;</p><p class=\"wh-p\">SB-26 的多重闪光模式是在相机快门打开期间，以设定的恒定发光量闪光，按照设定的发光间隔和发光次数重复发光的模式。</p><p class=\"wh-p wh-procedure-heading\">[操作方法]</p><p class=\"wh-p\">① 将相机的曝光模式设为手动（M）。</p><p class=\"wh-p\">② 将 SB-26 的 &lt;模式选择器&gt; 设为多重闪光模式。</p><p class=\"wh-p\">③ 将 SB-26 的 &lt;同步选择器&gt; 设为 NORMAL。</p><p class=\"wh-p\">④ 按下 SB-26 的 &lt;M&gt; 按钮，设置发光量。</p><p class=\"wh-p wh-footnote\">＊发光量可设定为 1/8、1/16、1/32、1/64 之一。</p><p class=\"wh-p\">⑤ 操作 SB-26 的 &lt;SEL&gt; 按钮和 &lt;▲&gt; 或 &lt;▼&gt; 按钮，设置发光间隔（频率 Hz）和发光次数（重复次数）。</p><p class=\"wh-p wh-footnote\">＊发光次数受所设定的发光间隔和发光量限制，无法设定超过限制的次数。</p><p class=\"wh-p\">⑥ 设置相机的快门速度。</p><p class=\"wh-p wh-footnote\">＊多重闪光拍摄时，快门需保持打开直至按设定间隔与次数的全部闪光完成；快门速度以「发光次数÷发光间隔（Hz）」秒为参考，设为该值或更低。</p><p class=\"wh-p\">⑦ 参考 SB-26 的条形显示，设定光圈值进行拍摄。</p><p class=\"wh-p wh-footnote\">＊多重闪光拍摄时为防止手抖，建议使用三脚架。</p></div></div>", "bodyFormat": "html", "displayTitle": "多重闪光拍摄"}}}, {"tocLevel": 3, "tocIndex": 5, "searchText": "TTL 自动调光欠曝指示 ＜TTL自动调光欠曝显示＞相机安装SB-26进行TTL自动调光拍摄时，若闪光灯全功率闪光，SB-26和相机的就绪指示灯将闪烁约3秒，同时SB-26的显示面板右上角会以档数显示欠曝量参考值数秒。此外，全功率闪光后，按下SB-26的<照明器>按钮，可随时重新确认当时的欠曝量。重拍时，请以此作为重新设置光圈等的参考。", "tocChildCount": 0, "id": "f90j.t02cab4", "tocParent": "f90j.t0285ca", "strings": {"zh-Hans": {"title": "TTL 自动调光欠曝指示", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;TTL 自动调光欠曝指示&gt;</p><p class=\"wh-p\">相机安装 SB-26 进行 TTL 自动调光拍摄时，若闪光灯全功率发光，SB-26 和相机的就绪指示灯将闪烁约 3 秒，同时 SB-26 显示面板右上角会以档数显示欠曝量参考值数秒。此外，全功率发光后，按下 SB-26 的 &lt;照明器&gt; 按钮，可随时重新确认当时的欠曝量。重拍时，请以此作为重新设置光圈等的参考。</p></div></div>", "bodyFormat": "html", "displayTitle": "TTL 自动调光欠曝指示"}}}, {"tocLevel": 3, "tocIndex": 6, "searchText": "无线多灯拍摄 <无线多灯拍摄>使用SB-26进行被摄体布光时，可进行无线多灯拍摄。装在相机上的主闪光灯开始发光，远处的从属SB-26通过传感器检测并闪光。此时可选择主从同时闪光的从属·S模式，以及主闪光结束后从属闪光的从属·D模式。 从属·D模式下，因为可以进行不受从属闪光影响的主灯自动调光，所以用于从属辅助灯强烈照明背景等情况。 [操作方法] ①将SB-26前面的<无线从属选择器>设为S（从属·S模式）或D（从属·D模式）。 ②将SB-26的<模式选择器>设为M或A。确认从属侧SB-26与被摄体的距离，设定闪光量。 ＊当主从双方都使用SB-26时，<无线从属选择器>设为相同设置。＊在从属D模式下，快门速度设定为低于1/125秒。但仅使用SB-26时，快门速度自动低于1/125秒。", "tocChildCount": 0, "id": "f90j.t02ccac", "tocParent": "f90j.t0285ca", "strings": {"zh-Hans": {"title": "无线多灯拍摄", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;无线多灯拍摄&gt;</p><p class=\"wh-p\">使用 SB-26 进行被摄体布光时，可进行无线多灯拍摄。装在相机上的主控闪光灯开始发光时，远处的从属 SB-26 通过传感器检测并闪光。此时可选择主从同时闪光的从属·S 模式，以及主闪光结束后从属闪光的从属·D 模式。</p><p class=\"wh-p\">从属·D 模式下可进行不受从属闪光影响的主灯自动调光，适用于从属辅助灯强烈照明背景等情况。</p><p class=\"wh-p wh-procedure-heading\">[操作方法]</p><p class=\"wh-p\">① 将 SB-26 前面的 &lt;无线从属选择器&gt; 设为 S（从属·S 模式）或 D（从属·D 模式）。</p><p class=\"wh-p\">② 将 SB-26 的 &lt;模式选择器&gt; 设为 M 或 A。确认从属侧 SB-26 与被摄体的距离，设定闪光量。</p><p class=\"wh-p wh-footnote\">＊当主从双方都使用 SB-26 时，&lt;无线从属选择器&gt; 应设为相同设置。</p><p class=\"wh-p wh-footnote\">＊从属·D 模式下，快门速度应设定为低于 1/125 秒。但仅使用 SB-26 时，快门速度会自动低于 1/125 秒。</p></div></div>", "bodyFormat": "html", "displayTitle": "无线多灯拍摄"}}}, {"tocLevel": 2, "tocIndex": 1, "searchText": "快门线 MC-20 ＜遥控线 MC-20＞MC-20 是带定时器的遥控线，连接相机后除了半按快门、释放操作外，还可选择在设定时间内进行长时间曝光的“LONG EXP”模式，以及第一次释放操作打开快门、第二次释放操作关闭快门的“TIME”模式。在“TIME”模式下会显示拍摄经过时间。此外，“LONG EXP”和“TIME”模式下，释放过程中每秒可发出电子音。按下照明器按钮还可点亮 LCD 显示屏照明。 使用带 10 针终端的相机时无需电池。 在带 2 针遥控终端或带马达驱动器的相机上使用时，请使用转换线 MC-26，并在 MC-20 中放入电池（CR2032）。 另外，使用“LONG EXP”模式和“TIME”模式时，请将相机设置为“buLb”。此时，自定义设置中的 B门/定时选择也请设为“B门”。", "tocChildCount": 0, "id": "f90j.t02d174", "tocParent": "f90j.t028490", "strings": {"zh-Hans": {"title": "快门线 MC-20", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;快门线 MC-20&gt;</p><p class=\"wh-p\">MC-20 是带定时器的遥控线，连接相机后除了半按快门、释放操作外，还可选择在设定时间内进行长时间曝光的「LONG EXP」模式，以及第一次释放操作打开快门、第二次释放操作关闭快门的「TIME」模式。在「TIME」模式下会显示拍摄经过时间。</p><p class=\"wh-p\">此外，「LONG EXP」和「TIME」模式下，释放过程中每秒可发出电子音。按下 &lt;照明器&gt; 按钮还可点亮 LCD 显示屏照明。</p><p class=\"wh-p\">使用带 10 针端子的相机时无需电池。</p><p class=\"wh-p\">在带 2 针遥控终端或带马达驱动器的相机上使用时，请使用转换线 MC-26，并在 MC-20 中放入电池（CR2032）。</p><p class=\"wh-p\">另外，使用「LONG EXP」模式和「TIME」模式时，请将相机设置为「buLb」。此时，自定义设置中的 B 门/定时选择也请设为「B 门」。</p></div></div>", "bodyFormat": "html", "displayTitle": "快门线 MC-20"}}}, {"tocLevel": 2, "tocIndex": 2, "searchText": "Modulite遥控套装 ML-3 ＜光遥控组件 ML-3＞光遥控组件ML-3是一款可无线操作带有10针端子的相机的配件。有2个频道，相机控制可实现单张释放、连拍释放、延时释放操作。此外，在自动触发模式下，可在被摄体遮挡发射机与接收机之间时释放快门，进行无人拍摄。此时的相机控制可进行单张释放、2秒连续释放，以及用于确认发射机与接收机之间通信是否可靠的测试操作。另外，频道1和2与ML-2信号兼容，因此可将ML-2的发射器与ML-3的接收器组合使用，实现更远距离的遥控操作。 此时，ML-2的ALL频道也可使用。", "tocChildCount": 0, "id": "f90j.t02d4f1", "tocParent": "f90j.t028490", "strings": {"zh-Hans": {"title": "Modulite遥控套装 ML-3", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;Modulite遥控套装 ML-3&gt;</p><p class=\"wh-p\">Modulite 遥控套装 ML-3 是一款可无线操作带有 10 针端子相机的配件。设有 2 个频道，相机控制可实现单张释放、连拍释放、延时释放操作。</p><p class=\"wh-p\">此外，在自动触发模式下，可在被摄体遮挡发射机与接收机之间时释放快门，进行无人拍摄。此时的相机控制可进行单张释放、2 秒连续释放，以及用于确认发射机与接收机之间通信是否可靠的测试操作。</p><p class=\"wh-p\">另外，频道 1 和 2 与 ML-2 信号兼容，因此可将 ML-2 的发射器与 ML-3 的接收器组合使用，实现更远距离的遥控操作。</p><p class=\"wh-p\">此时，ML-2 的 ALL 频道也可使用。</p></div></div>", "bodyFormat": "html", "displayTitle": "Modulite遥控套装 ML-3"}}}, {"tocLevel": 2, "tocIndex": 3, "searchText": "竖拍手柄 MB-10 ＜竖拍手柄 MB-10＞竖拍手柄MB-10配备竖拍快门按钮，是竖拍使用F90X时的便利配件。使用时从F90X取下AA电池架MS-8，安装MB-10。电池除4节AA电池外，还可通过另购的锂电池架MS-11并用，使用2节CR123A锂电池。", "tocChildCount": 0, "id": "f90j.t02d7e8", "tocParent": "f90j.t028490", "strings": {"zh-Hans": {"title": "竖拍手柄 MB-10", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p wh-topic-heading\">&lt;竖拍手柄 MB-10&gt;</p><p class=\"wh-p\">竖拍手柄 MB-10 配备竖拍快门按钮，是竖拍使用 F90X 时的便利配件。</p><p class=\"wh-p\">使用时从 F90X 取下 AA 电池架 MS-8，安装 MB-10。</p><p class=\"wh-p\">电池除 4 节 AA 电池外，还可通过另购的锂电池架 MS-11 并用，使用 2 节 CR123A 锂电池。</p></div></div>", "bodyFormat": "html", "displayTitle": "竖拍手柄 MB-10"}}}, {"tocLevel": 2, "tocIndex": 4, "searchText": "E型取景屏 ＜E型取景屏＞除了标配的B型Clear Matte Screen II之外，还备有E型可更换取景屏。E型取景屏是在B型Clear Matte Screen II上添加了方格网，在一般拍摄中有利于构图决定，尤其适合使用PC尼克尔镜头进行移轴拍摄或翻拍等。更换取景屏时，请取下镜头，从卡口处使用更换取景屏附带的镊子进行操作。", "tocChildCount": 0, "id": "f90j.t030043", "tocParent": "f90j.t028490", "strings": {"zh-Hans": {"title": "E型取景屏", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\">除了标配的B型Clear Matte Screen II之外，还备有E型可更换取景屏。E型取景屏是在B型Clear Matte Screen II上添加了方格网，在一般拍摄中有利于构图决定，尤其适合使用PC尼克尔镜头进行移轴拍摄或翻拍等。更换取景屏时，请取下镜头，从卡口处使用更换取景屏附带的镊子进行操作。</p></div></div>", "bodyFormat": "html", "displayTitle": "E型取景屏"}}}, {"tocLevel": 1, "listHidden": true, "tocIndex": 4, "searchText": "t03023b", "tocChildCount": 0, "id": "f90j.t03023b", "tocParent": "f90j.t00000c", "strings": {"zh-Hans": {"title": "t03023b", "body": "<div class=\"winhelp-topic\"><div class=\"wh-block wh-left\"><p class=\"wh-p\"><span class=\"wh-bold wh-fsize-28\"><span class=\"wh-fsize-20\"></span></span></p></div></div>", "bodyFormat": "html", "displayTitle": "t03023b"}}}]}]};
